// SPDX-License-Identifier: Apache-2.0
// specs/compiler/parser.t27
// T27 Parser Specification -- Self-hosting compiler core
// phi^2 + 1/phi^2 = 3 | TRINITY
//
// This module defines the complete recursive descent parser for the T27 language.
// It is a 1:1 port of bootstrap/src/compiler.rs Parser to t27 spec format.

module Parsing {
    use base::types;
    use compiler::lexer;

    // ====================================================================
    // 1. AST Node Types
    // ====================================================================

    const MAX_CHILDREN: u32 = 32;

    enum NodeKind {
        Module = 0,
        UseDecl = 1,
        ConstDecl = 2,
        VarDecl = 3,
        FnDecl = 4,
        EnumDecl = 5,
        StructDecl = 6,
        TestBlock = 7,
        InvariantBlock = 8,
        BenchBlock = 9,

        StmtLocal = 10,
        StmtAssign = 11,
        StmtIf = 12,
        StmtWhile = 13,
        StmtFor = 14,
        StmtExpr = 15,
        StmtReturn = 16,
        StmtBreak = 17,
        StmtContinue = 18,

        ExprLiteral = 20,
        ExprIdentifier = 21,
        ExprBinary = 22,
        ExprUnary = 23,
        ExprCall = 24,
        ExprFieldAccess = 25,
        ExprIndex = 26,
        ExprSwitch = 27,
        ExprIf = 28,
        ExprStructLit = 29,
        ExprEnumValue = 30,
        ExprReturn = 31,
        ExprArrayLiteral = 32,
    }

    struct Node {
        kind: NodeKind;
        name: str;
        value: str;
        extra_type: str;
        extra_field: str;
        extra_size: str;
        extra_kind: str;
        extra_op: str;
        extra_pub: bool;
        extra_mutable: bool;
        extra_return_type: str;
        child_count: u32;
        children: [MAX_CHILDREN]Node;
    }

    // ====================================================================
    // 2. Parser State
    // ====================================================================

    struct Parser {
        lexer: lexer::Lexer;
        current: lexer::Token;
        peek: lexer::Token;
        had_error: bool;
        error_msg: str;
    }

    fn parser_init(lex: lexer::Lexer) -> Parser {
        var p = Parser{};
        p.lexer = lex;
        p.advance();
        p.advance();
        return p;
    }

    // ====================================================================
    // 3. Movement Primitives
    // ====================================================================

    fn advance(self: *Parser) -> void {
        self.current = self.peek;
        self.peek = lexer::next_token(self.lexer);
    }

    fn check(self: *Parser, kind: lexer::TokenKind) -> bool {
        return self.current.kind == kind;
    }

    fn check_peek(self: *Parser, kind: lexer::TokenKind) -> bool {
        return self.peek.kind == kind;
    }

    fn expect(self: *Parser, kind: lexer::TokenKind) -> bool {
        if (self.check(kind)) {
            self.advance();
            return true;
        }
        self.had_error = true;
        self.error_msg = "Expected token";
        return false;
    }

    fn error(self: *Parser, msg: str) -> void {
        self.had_error = true;
        self.error_msg = msg;
    }

    fn get_error(self: Parser) -> str {
        return self.error_msg;
    }

    // ====================================================================
    // 4. Error Recovery
    // ====================================================================

    fn skip_brace_body(self: *Parser) -> bool {
        var depth: i32 = 1;
        while (depth > 0) {
            if (self.current.kind == lexer::TokenKind::Eof) {
                self.error("Unexpected EOF inside brace body");
                return false;
            }
            if (self.current.kind == lexer::TokenKind::LBrace) {
                depth = depth + 1;
            } else if (self.current.kind == lexer::TokenKind::RBrace) {
                depth = depth - 1;
                if (depth == 0) {
                    return true;
                }
            }
            self.advance();
        }
        return true;
    }

    fn skip_to_semicolon(self: *Parser) -> void {
        var bracket_depth: i32 = 0;
        var paren_depth: i32 = 0;
        while (self.current.kind != lexer::TokenKind::Eof) {
            if (self.current.kind == lexer::TokenKind::Semicolon 
                and bracket_depth == 0 
                and paren_depth == 0) {
                self.advance();
                return;
            }
            if (self.current.kind == lexer::TokenKind::LBrace) {
                self.advance();
                self.skip_brace_body();
                if (self.current.kind == lexer::TokenKind::RBrace) {
                    self.advance();
                }
            } else if (self.current.kind == lexer::TokenKind::LBracket) {
                bracket_depth = bracket_depth + 1;
                self.advance();
            } else if (self.current.kind == lexer::TokenKind::RBracket) {
                bracket_depth = bracket_depth - 1;
                self.advance();
            } else if (self.current.kind == lexer::TokenKind::LParen) {
                paren_depth = paren_depth + 1;
                self.advance();
            } else if (self.current.kind == lexer::TokenKind::RParen) {
                paren_depth = paren_depth - 1;
                self.advance();
            } else {
                self.advance();
            }
        }
    }

    fn is_top_level_start(self: Parser) -> bool {
        return self.current.kind == lexer::TokenKind::KwPub
            or self.current.kind == lexer::TokenKind::KwFn
            or self.current.kind == lexer::TokenKind::KwEnum
            or self.current.kind == lexer::TokenKind::KwStruct
            or self.current.kind == lexer::TokenKind::KwTest
            or self.current.kind == lexer::TokenKind::KwInvariant
            or self.current.kind == lexer::TokenKind::KwBench
            or self.current.kind == lexer::TokenKind::KwUse
            or self.current.kind == lexer::TokenKind::KwUsing
            or self.current.kind == lexer::TokenKind::KwModule
            or self.current.kind == lexer::TokenKind::RBrace
            or self.current.kind == lexer::TokenKind::Eof;
    }

    fn skip_to_next_top_level(self: *Parser) -> void {
        var paren_depth: i32 = 0;
        var bracket_depth: i32 = 0;
        while (true) {
            if (self.current.kind == lexer::TokenKind::Eof) {
                break;
            }
            if (self.current.kind == lexer::TokenKind::LBrace) {
                self.advance();
                self.skip_brace_body();
                if (self.current.kind == lexer::TokenKind::RBrace) {
                    self.advance();
                }
            }
            if (self.current.kind == lexer::TokenKind::LParen) {
                paren_depth = paren_depth + 1;
                self.advance();
            }
            if (self.current.kind == lexer::TokenKind::RParen) {
                paren_depth = paren_depth - 1;
                self.advance();
            }
            if (self.current.kind == lexer::TokenKind::LBracket) {
                bracket_depth = bracket_depth + 1;
                self.advance();
            }
            if (self.current.kind == lexer::TokenKind::RBracket) {
                bracket_depth = bracket_depth - 1;
                self.advance();
            }
            if (paren_depth == 0 and bracket_depth == 0 and self.is_top_level_start()) {
                break;
            }
            self.advance();
        }
    }

    fn recover_to_stmt_boundary(self: *Parser) -> void {
        var brace_depth: i32 = 0;
        while (true) {
            if (self.current.kind == lexer::TokenKind::Eof) {
                break;
            }
            if (self.current.kind == lexer::TokenKind::Semicolon and brace_depth == 0) {
                self.advance();
                break;
            }
            if (self.current.kind == lexer::TokenKind::RBrace and brace_depth == 0) {
                break;
            }
            if (self.current.kind == lexer::TokenKind::LBrace) {
                brace_depth = brace_depth + 1;
                self.advance();
            } else if (self.current.kind == lexer::TokenKind::RBrace) {
                brace_depth = brace_depth - 1;
                self.advance();
            } else {
                self.advance();
            }
        }
    }

    // ====================================================================
    // 5. Type Annotation Parser
    // ====================================================================

    fn parse_type_annotation(self: *Parser) -> str {
        var ty: str = "";

        if (self.check(lexer::TokenKind::Star)) {
            self.advance();
            ty = ty ++ "*";
            if (self.check(lexer::TokenKind::KwConst)) {
                self.advance();
                ty = ty ++ "const ";
            }
            if (self.check(lexer::TokenKind::Ident)) {
                ty = ty ++ self.current.lexeme;
                self.advance();
            }
            return ty;
        }

        while (self.check(lexer::TokenKind::LBracket)) {
            self.advance();
            ty = ty ++ "[";
            while (self.current.kind != lexer::TokenKind::RBracket 
                   and self.current.kind != lexer::TokenKind::Eof) {
                ty = ty ++ self.current.lexeme;
                self.advance();
            }
            ty = ty ++ "]";
            if (self.check(lexer::TokenKind::RBracket)) {
                self.advance();
            }
        }

        if (self.check(lexer::TokenKind::KwConst)) {
            if (ty != "") {
                ty = ty ++ "const ";
            } else {
                ty = "const ";
            }
            self.advance();
        }

        if (self.check(lexer::TokenKind::Star)) {
            self.advance();
            ty = ty ++ "*";
            if (self.check(lexer::TokenKind::KwConst)) {
                self.advance();
                ty = ty ++ "const ";
            }
        }

        if (self.check(lexer::TokenKind::Ident)) {
            ty = ty ++ self.current.lexeme;
            self.advance();
        } else if (self.check(lexer::TokenKind::KwVoid)) {
            ty = ty ++ "void";
            self.advance();
        }

        return ty;
    }

    // ====================================================================
    // 6. Expression Parser (Precedence Levels)
    // ====================================================================

    fn node_new(kind: NodeKind) -> Node {
        return Node{
            kind = kind,
            name = "",
            value = "",
            extra_type = "",
            extra_field = "",
            extra_size = "",
            extra_kind = "",
            extra_op = "",
            extra_pub = false,
            extra_mutable = false,
            extra_return_type = "",
            child_count = 0,
            children = [Node{}; MAX_CHILDREN],
        };
    }

    fn add_child(parent: *Node, child: Node) -> void {
        if (parent.child_count < MAX_CHILDREN) {
            parent.children[parent.child_count] = child;
            parent.child_count = parent.child_count + 1;
        }
    }

    fn parse_expr(self: *Parser) -> Node {
        return self.parse_expr_or();
    }

    fn parse_expr_or(self: *Parser) -> Node {
        var left = self.parse_expr_and();
        while (self.check(lexer::TokenKind::KwOr)) {
            self.advance();
            const right = self.parse_expr_and();
            var node = node_new(NodeKind::ExprBinary);
            node.extra_op = "or";
            add_child(&node, left);
            add_child(&node, right);
            left = node;
        }
        return left;
    }

    fn parse_expr_and(self: *Parser) -> Node {
        var left = self.parse_expr_comparison();
        while (self.check(lexer::TokenKind::KwAnd)) {
            self.advance();
            const right = self.parse_expr_comparison();
            var node = node_new(NodeKind::ExprBinary);
            node.extra_op = "and";
            add_child(&node, left);
            add_child(&node, right);
            left = node;
        }
        return left;
    }

    fn parse_expr_comparison(self: *Parser) -> Node {
        var left = self.parse_expr_bitor();
        while (self.check(lexer::TokenKind::Eq)
               or self.check(lexer::TokenKind::Neq)
               or self.check(lexer::TokenKind::Lt)
               or self.check(lexer::TokenKind::Gt)
               or self.check(lexer::TokenKind::Lte)
               or self.check(lexer::TokenKind::Gte)
               or self.check(lexer::TokenKind::DotDot)) {
            const op = self.current.lexeme;
            self.advance();
            const right = self.parse_expr_bitor();
            var node = node_new(NodeKind::ExprBinary);
            node.extra_op = op;
            add_child(&node, left);
            add_child(&node, right);
            left = node;
        }
        return left;
    }

    fn parse_expr_bitor(self: *Parser) -> Node {
        var left = self.parse_expr_bitxor();
        while (self.check(lexer::TokenKind::Pipe)) {
            const op = self.current.lexeme;
            self.advance();
            const right = self.parse_expr_bitxor();
            var node = node_new(NodeKind::ExprBinary);
            node.extra_op = op;
            add_child(&node, left);
            add_child(&node, right);
            left = node;
        }
        return left;
    }

    fn parse_expr_bitxor(self: *Parser) -> Node {
        var left = self.parse_expr_bitand();
        while (self.check(lexer::TokenKind::Caret)) {
            const op = self.current.lexeme;
            self.advance();
            const right = self.parse_expr_bitand();
            var node = node_new(NodeKind::ExprBinary);
            node.extra_op = op;
            add_child(&node, left);
            add_child(&node, right);
            left = node;
        }
        return left;
    }

    fn parse_expr_bitand(self: *Parser) -> Node {
        var left = self.parse_expr_shift();
        while (self.check(lexer::TokenKind::Amp)) {
            const op = self.current.lexeme;
            self.advance();
            const right = self.parse_expr_shift();
            var node = node_new(NodeKind::ExprBinary);
            node.extra_op = op;
            add_child(&node, left);
            add_child(&node, right);
            left = node;
        }
        return left;
    }

    fn parse_expr_shift(self: *Parser) -> Node {
        var left = self.parse_expr_additive();
        while (self.check(lexer::TokenKind::ShiftLeft) or self.check(lexer::TokenKind::ShiftRight)) {
            const op = self.current.lexeme;
            self.advance();
            const right = self.parse_expr_additive();
            var node = node_new(NodeKind::ExprBinary);
            node.extra_op = op;
            add_child(&node, left);
            add_child(&node, right);
            left = node;
        }
        return left;
    }

    fn parse_expr_additive(self: *Parser) -> Node {
        var left = self.parse_expr_multiplicative();
        while (self.check(lexer::TokenKind::Plus) 
               or self.check(lexer::TokenKind::Minus) 
               or self.check(lexer::TokenKind::PlusPercent)) {
            const op = self.current.lexeme;
            self.advance();
            const right = self.parse_expr_multiplicative();
            var node = node_new(NodeKind::ExprBinary);
            node.extra_op = op;
            add_child(&node, left);
            add_child(&node, right);
            left = node;
        }
        return left;
    }

    fn parse_expr_multiplicative(self: *Parser) -> Node {
        var left = self.parse_expr_unary();
        while (self.check(lexer::TokenKind::Star) 
               or self.check(lexer::TokenKind::Slash) 
               or self.check(lexer::TokenKind::Percent) 
               or self.check(lexer::TokenKind::Power)) {
            const op = self.current.lexeme;
            self.advance();
            const right = self.parse_expr_unary();
            var node = node_new(NodeKind::ExprBinary);
            node.extra_op = op;
            add_child(&node, left);
            add_child(&node, right);
            left = node;
        }
        return left;
    }

    fn parse_expr_unary(self: *Parser) -> Node {
        if (self.check(lexer::TokenKind::Minus) 
            or self.check(lexer::TokenKind::Bang) 
            or self.check(lexer::TokenKind::Tilde) 
            or self.check(lexer::TokenKind::Amp)) {
            const op = self.current.lexeme;
            self.advance();
            const operand = self.parse_expr_unary();
            var node = node_new(NodeKind::ExprUnary);
            node.extra_op = op;
            add_child(&node, operand);
            return node;
        }
        return self.parse_expr_postfix();
    }

    fn parse_expr_postfix(self: *Parser) -> Node {
        var expr = self.parse_expr_primary();

        while (true) {
            if (self.check(lexer::TokenKind::Dot)) {
                self.advance();
                if (self.check(lexer::TokenKind::Star)) {
                    self.advance();
                    var deref = node_new(NodeKind::ExprFieldAccess);
                    deref.name = "*";
                    add_child(&deref, expr);
                    expr = deref;
                } else if (self.check(lexer::TokenKind::Ident)) {
                    const field = self.current.lexeme;
                    self.advance();
                    if (self.check(lexer::TokenKind::LParen)) {
                        expr = self.parse_call_args_internal(field, expr);
                    } else {
                        var fa = node_new(NodeKind::ExprFieldAccess);
                        fa.name = field;
                        add_child(&fa, expr);
                        expr = fa;
                    }
                } else {
                    break;
                }
            } else if (self.check(lexer::TokenKind::LBracket)) {
                self.advance();
                const index = self.parse_expr();
                self.expect(lexer::TokenKind::RBracket);
                var idx_node = node_new(NodeKind::ExprIndex);
                add_child(&idx_node, expr);
                add_child(&idx_node, index);
                expr = idx_node;
            } else if (self.check(lexer::TokenKind::LParen)) {
                break;
            } else {
                break;
            }
        }
        return expr;
    }

    fn parse_call_args_internal(self: *Parser, name: str, base_expr: Node) -> Node {
        self.advance();
        var call = node_new(NodeKind::ExprCall);
        call.name = name;
        add_child(&call, base_expr);

        while (self.current.kind != lexer::TokenKind::RParen 
               and self.current.kind != lexer::TokenKind::Eof) {
            const arg = self.parse_expr();
            add_child(&call, arg);
            if (self.check(lexer::TokenKind::Comma)) {
                self.advance();
            }
        }
        self.expect(lexer::TokenKind::RParen);
        return call;
    }

    fn parse_expr_primary(self: *Parser) -> Node {
        if (self.check(lexer::TokenKind::Number)) {
            var node = node_new(NodeKind::ExprLiteral);
            node.value = self.current.lexeme;
            self.advance();
            return node;
        }

        if (self.check(lexer::TokenKind::CharLiteral)) {
            var node = node_new(NodeKind::ExprLiteral);
            node.value = self.current.lexeme;
            self.advance();
            return node;
        }

        if (self.check(lexer::TokenKind::StringLit)) {
            var node = node_new(NodeKind::ExprLiteral);
            node.value = self.current.lexeme;
            self.advance();
            return node;
        }

        if (self.check(lexer::TokenKind::KwTrue) or self.check(lexer::TokenKind::KwFalse)) {
            var node = node_new(NodeKind::ExprLiteral);
            node.value = self.current.lexeme;
            self.advance();
            return node;
        }

        if (self.check(lexer::TokenKind::Dot)) {
            self.advance();
            if (self.check(lexer::TokenKind::Ident)) {
                var node = node_new(NodeKind::ExprEnumValue);
                node.name = self.current.lexeme;
                self.advance();
                return node;
            }
            return node_new(NodeKind::ExprLiteral);
        }

        if (self.check(lexer::TokenKind::Ident)) {
            const name = self.current.lexeme;
            self.advance();
            if (self.check(lexer::TokenKind::LBrace)) {
                return self.parse_struct_literal(name);
            }
            if (self.check(lexer::TokenKind::LParen)) {
                return self.parse_call_args(name);
            }
            var node = node_new(NodeKind::ExprIdentifier);
            node.name = name;
            return node;
        }

        if (self.check(lexer::TokenKind::LParen)) {
            self.advance();
            const inner = self.parse_expr();
            self.expect(lexer::TokenKind::RParen);
            return inner;
        }

        if (self.check(lexer::TokenKind::KwIf)) {
            return self.parse_if_expr();
        }

        if (self.check(lexer::TokenKind::KwSwitch)) {
            return self.parse_switch_expr();
        }

        if (self.check(lexer::TokenKind::KwTry)) {
            self.advance();
            const inner = self.parse_expr_postfix();
            var node = node_new(NodeKind::ExprUnary);
            node.extra_op = "try ";
            add_child(&node, inner);
            return node;
        }

        if (self.check(lexer::TokenKind::LBracket)) {
            return self.parse_array_literal();
        }

        return node_new(NodeKind::ExprLiteral);
    }

    fn parse_call_args(self: *Parser, name: str) -> Node {
        self.advance();
        var call = node_new(NodeKind::ExprCall);
        call.name = name;

        while (self.current.kind != lexer::TokenKind::RParen 
               and self.current.kind != lexer::TokenKind::Eof) {
            const arg = self.parse_expr();
            add_child(&call, arg);
            if (self.check(lexer::TokenKind::Comma)) {
                self.advance();
            }
        }
        self.expect(lexer::TokenKind::RParen);
        return call;
    }

    fn parse_struct_literal(self: *Parser, name: str) -> Node {
        self.advance();
        var lit = node_new(NodeKind::ExprStructLit);
        lit.name = name;

        while (self.current.kind != lexer::TokenKind::RBrace 
               and self.current.kind != lexer::TokenKind::Eof) {
            var field_name = "";
            if (self.check(lexer::TokenKind::Dot)) {
                self.advance();
                if (self.check(lexer::TokenKind::Ident)) {
                    field_name = self.current.lexeme;
                    self.advance();
                }
            } else if (self.check(lexer::TokenKind::Ident)) {
                field_name = self.current.lexeme;
                self.advance();
            }

            if (self.check(lexer::TokenKind::Equals)) {
                self.advance();
            }

            const val = self.parse_expr();
            var field = node_new(NodeKind::ExprFieldAccess);
            field.name = field_name;
            add_child(&field, val);
            add_child(&lit, field);

            if (self.check(lexer::TokenKind::Comma)) {
                self.advance();
            }
        }
        self.expect(lexer::TokenKind::RBrace);
        return lit;
    }

    fn parse_array_literal(self: *Parser) -> Node {
        var node = node_new(NodeKind::ExprArrayLiteral);
        self.advance();

        if (self.current.kind == lexer::TokenKind::RBracket) {
            self.advance();
        } else {
            var bracket_text = "";
            while (self.current.kind != lexer::TokenKind::RBracket
                   and self.current.kind != lexer::TokenKind::Eof) {
                bracket_text = bracket_text ++ self.current.lexeme;
                self.advance();
            }
            node.extra_size = bracket_text;
            self.expect(lexer::TokenKind::RBracket);
        }

        if (self.check(lexer::TokenKind::Ident)) {
            node.extra_type = self.current.lexeme;
            self.advance();
        }

        if (self.check(lexer::TokenKind::LBrace)) {
            self.advance();
            if (self.current.kind != lexer::TokenKind::RBrace) {
                var elem = self.parse_expr();
                add_child(&node, elem);
                while (self.check(lexer::TokenKind::Comma)) {
                    self.advance();
                    if (self.current.kind == lexer::TokenKind::RBrace) {
                        break;
                    }
                    elem = self.parse_expr();
                    add_child(&node, elem);
                }
            }
            self.expect(lexer::TokenKind::RBrace);
        }

        if (self.check(lexer::TokenKind::Power)) {
            self.advance();
            var count = self.parse_expr();
            var repeat_node = node_new(NodeKind::ExprBinary);
            repeat_node.extra_op = "**";
            add_child(&repeat_node, node);
            add_child(&repeat_node, count);
            return repeat_node;
        }

        return node;
    }

    fn parse_if_expr(self: *Parser) -> Node {
        self.advance();
        var node = node_new(NodeKind::ExprIf);

        self.expect(lexer::TokenKind::LParen);
        const cond = self.parse_expr();
        self.expect(lexer::TokenKind::RParen);
        add_child(&node, cond);

        const then_expr = self.parse_expr();
        add_child(&node, then_expr);

        if (self.check(lexer::TokenKind::KwElse)) {
            self.advance();
            const else_expr = self.parse_expr();
            add_child(&node, else_expr);
        }

        return node;
    }

    fn parse_switch_expr(self: *Parser) -> Node {
        self.advance();
        var sw = node_new(NodeKind::ExprSwitch);

        self.expect(lexer::TokenKind::LParen);
        const val = self.parse_expr();
        self.expect(lexer::TokenKind::RParen);
        add_child(&sw, val);

        self.expect(lexer::TokenKind::LBrace);

        while (self.current.kind != lexer::TokenKind::RBrace 
               and self.current.kind != lexer::TokenKind::Eof) {
            var arm = node_new(NodeKind::ConstDecl);

            if (self.check(lexer::TokenKind::Dot)) {
                self.advance();
                if (self.check(lexer::TokenKind::Ident)) {
                    arm.name = self.current.lexeme;
                    self.advance();
                }
            } else if (self.check(lexer::TokenKind::KwElse)) {
                arm.name = "else";
                self.advance();
            } else if (self.check(lexer::TokenKind::Minus)) {
                arm.name = "-";
                self.advance();
                if (self.check(lexer::TokenKind::Number)) {
                    arm.name = arm.name ++ self.current.lexeme;
                    self.advance();
                }
            } else if (self.check(lexer::TokenKind::Ident) or self.check(lexer::TokenKind::Number)) {
                arm.name = self.current.lexeme;
                self.advance();
            }

            if (self.check(lexer::TokenKind::FatArrow)) {
                self.advance();
            }

            const arm_expr = self.parse_expr();
            add_child(&arm, arm_expr);
            add_child(&sw, arm);

            if (self.check(lexer::TokenKind::Comma)) {
                self.advance();
            }
        }

        self.expect(lexer::TokenKind::RBrace);
        return sw;
    }

    // ====================================================================
    // 7. Statement Parser
    // ====================================================================

    fn parse_body_stmt(self: *Parser) -> Node {
        if (self.check(lexer::TokenKind::KwConst) or self.check(lexer::TokenKind::KwVar)) {
            return self.parse_local_decl();
        }

        if (self.check(lexer::TokenKind::KwReturn)) {
            return self.parse_return_statement();
        }

        if (self.check(lexer::TokenKind::KwIf)) {
            return self.parse_if_stmt();
        }

        if (self.check(lexer::TokenKind::KwWhile)) {
            return self.parse_while_stmt();
        }

        if (self.check(lexer::TokenKind::KwFor)) {
            return self.parse_for_stmt();
        }

        if (self.check(lexer::TokenKind::KwBreak)) {
            self.advance();
            if (self.check(lexer::TokenKind::Semicolon)) {
                self.advance();
            }
            return node_new(NodeKind::StmtBreak);
        }

        if (self.check(lexer::TokenKind::KwContinue)) {
            self.advance();
            if (self.check(lexer::TokenKind::Semicolon)) {
                self.advance();
            }
            return node_new(NodeKind::StmtContinue);
        }

        const expr = self.parse_expr();

        if (self.check(lexer::TokenKind::Equals)) {
            self.advance();
            const rhs = self.parse_expr();
            if (self.check(lexer::TokenKind::Semicolon)) {
                self.advance();
            }
            var assign = node_new(NodeKind::StmtAssign);
            add_child(&assign, expr);
            add_child(&assign, rhs);
            return assign;
        }

        if (self.check(lexer::TokenKind::PlusEquals)) {
            self.advance();
            const rhs = self.parse_expr();
            if (self.check(lexer::TokenKind::Semicolon)) {
                self.advance();
            }
            var assign = node_new(NodeKind::StmtAssign);
            assign.extra_op = "+=";
            add_child(&assign, expr);
            add_child(&assign, rhs);
            return assign;
        }

        if (self.check(lexer::TokenKind::Semicolon)) {
            self.advance();
        }
        var stmt = node_new(NodeKind::StmtExpr);
        add_child(&stmt, expr);
        return stmt;
    }

    fn parse_local_decl(self: *Parser) -> Node {
        var decl = node_new(NodeKind::StmtLocal);
        decl.extra_mutable = self.check(lexer::TokenKind::KwVar);
        self.advance();

        if (self.check(lexer::TokenKind::Ident)) {
            decl.name = self.current.lexeme;
            self.advance();
        }

        if (self.check(lexer::TokenKind::Colon)) {
            self.advance();
            decl.extra_type = self.parse_type_annotation();
        }

        if (self.check(lexer::TokenKind::Equals)) {
            self.advance();
            const init = self.parse_expr();
            add_child(&decl, init);
        }

        if (self.check(lexer::TokenKind::Semicolon)) {
            self.advance();
        }
        return decl;
    }

    fn parse_return_statement(self: *Parser) -> Node {
        var stmt = node_new(NodeKind::ExprReturn);
        self.advance();

        if (self.current.kind != lexer::TokenKind::Semicolon 
            and self.current.kind != lexer::TokenKind::RBrace) {
            const expr = self.parse_expr();
            add_child(&stmt, expr);
        }

        if (self.check(lexer::TokenKind::Semicolon)) {
            self.advance();
        }
        return stmt;
    }

    fn parse_if_stmt(self: *Parser) -> Node {
        var if_node = node_new(NodeKind::StmtIf);
        self.advance();

        self.expect(lexer::TokenKind::LParen);
        const cond = self.parse_expr();
        self.expect(lexer::TokenKind::RParen);
        add_child(&if_node, cond);

        if (self.check(lexer::TokenKind::LBrace)) {
            self.advance();
            var then_block = node_new(NodeKind::Module);
            then_block.name = "then";
            while (self.current.kind != lexer::TokenKind::RBrace 
                   and self.current.kind != lexer::TokenKind::Eof) {
                const s = self.parse_body_stmt();
                add_child(&then_block, s);
            }
            self.expect(lexer::TokenKind::RBrace);
            add_child(&if_node, then_block);
        } else {
            const stmt = self.parse_body_stmt();
            var then_block = node_new(NodeKind::Module);
            then_block.name = "then";
            add_child(&then_block, stmt);
            add_child(&if_node, then_block);
        }

        if (self.check(lexer::TokenKind::KwElse)) {
            self.advance();
            if (self.check(lexer::TokenKind::KwIf)) {
                const else_if = self.parse_if_stmt();
                var else_block = node_new(NodeKind::Module);
                else_block.name = "else";
                add_child(&else_block, else_if);
                add_child(&if_node, else_block);
            } else if (self.check(lexer::TokenKind::LBrace)) {
                self.advance();
                var else_block = node_new(NodeKind::Module);
                else_block.name = "else";
                while (self.current.kind != lexer::TokenKind::RBrace 
                       and self.current.kind != lexer::TokenKind::Eof) {
                    const s = self.parse_body_stmt();
                    add_child(&else_block, s);
                }
                self.expect(lexer::TokenKind::RBrace);
                add_child(&if_node, else_block);
            }
        }

        return if_node;
    }

    fn parse_while_stmt(self: *Parser) -> Node {
        var while_node = node_new(NodeKind::StmtWhile);
        self.advance();

        self.expect(lexer::TokenKind::LParen);
        const cond = self.parse_expr();
        self.expect(lexer::TokenKind::RParen);
        add_child(&while_node, cond);

        self.expect(lexer::TokenKind::LBrace);
        var body_block = node_new(NodeKind::Module);
        body_block.name = "body";
        while (self.current.kind != lexer::TokenKind::RBrace 
               and self.current.kind != lexer::TokenKind::Eof) {
            const s = self.parse_body_stmt();
            add_child(&body_block, s);
        }
        self.expect(lexer::TokenKind::RBrace);
        add_child(&while_node, body_block);

        return while_node;
    }

    fn parse_for_stmt(self: *Parser) -> Node {
        var for_node = node_new(NodeKind::StmtFor);
        self.advance();

        self.expect(lexer::TokenKind::LParen);
        while (self.current.kind != lexer::TokenKind::RParen 
               and self.current.kind != lexer::TokenKind::Eof) {
            const iter_expr = self.parse_expr();
            add_child(&for_node, iter_expr);
            if (self.check(lexer::TokenKind::Comma)) {
                self.advance();
            }
        }
        self.expect(lexer::TokenKind::RParen);

        if (self.check(lexer::TokenKind::Pipe)) {
            self.advance();
            while (self.current.kind != lexer::TokenKind::Pipe 
                   and self.current.kind != lexer::TokenKind::Eof) {
                if (self.check(lexer::TokenKind::Star)) {
                    self.advance();
                }
                if (self.check(lexer::TokenKind::Ident)) {
                    const param_name = self.current.lexeme;
                    self.advance();
                }
                if (self.check(lexer::TokenKind::Comma)) {
                    self.advance();
                }
            }
            self.expect(lexer::TokenKind::Pipe);
        }

        self.expect(lexer::TokenKind::LBrace);
        var body_block = node_new(NodeKind::Module);
        body_block.name = "body";
        while (self.current.kind != lexer::TokenKind::RBrace 
               and self.current.kind != lexer::TokenKind::Eof) {
            const s = self.parse_body_stmt();
            add_child(&body_block, s);
        }
        self.expect(lexer::TokenKind::RBrace);
        add_child(&for_node, body_block);

        return for_node;
    }

    fn parse_fn_body(self: *Parser) -> void {
        while (self.current.kind != lexer::TokenKind::RBrace 
               and self.current.kind != lexer::TokenKind::Eof) {
            const s = self.parse_body_stmt();
            if (s.kind != NodeKind::ExprLiteral) {
                // statement consumed
            }
        }
    }

    // ====================================================================
    // 8. Struct and Enum Body Parsers
    // ====================================================================

    fn parse_struct_body(self: *Parser, decl: *Node) -> void {
        while (self.current.kind != lexer::TokenKind::RBrace 
               and self.current.kind != lexer::TokenKind::Eof) {
            if (self.check(lexer::TokenKind::Ident)) {
                const field_name = self.current.lexeme;
                self.advance();

                var type_str = "";
                if (self.check(lexer::TokenKind::Colon)) {
                    self.advance();
                    while (self.current.kind != lexer::TokenKind::Comma
                           and self.current.kind != lexer::TokenKind::Semicolon
                           and self.current.kind != lexer::TokenKind::RBrace
                           and self.current.kind != lexer::TokenKind::Eof) {
                        type_str = type_str ++ self.current.lexeme;
                        self.advance();
                    }
                }

                var field = node_new(NodeKind::ExprIdentifier);
                field.name = field_name;
                field.extra_type = type_str;
                add_child(decl, field);

                if (self.check(lexer::TokenKind::Comma) or self.check(lexer::TokenKind::Semicolon)) {
                    self.advance();
                }
            } else {
                self.advance();
            }
        }
    }

    fn parse_enum_body(self: *Parser, decl: *Node) -> void {
        while (self.current.kind != lexer::TokenKind::RBrace 
               and self.current.kind != lexer::TokenKind::Eof) {
            if (self.check(lexer::TokenKind::Ident)) {
                const name = self.current.lexeme;
                self.advance();

                var value_str = "";
                if (self.check(lexer::TokenKind::Equals)) {
                    self.advance();
                    if (self.check(lexer::TokenKind::Minus)) {
                        value_str = "-";
                        self.advance();
                    }
                    if (self.check(lexer::TokenKind::Number)) {
                        value_str = value_str ++ self.current.lexeme;
                        self.advance();
                    } else if (self.check(lexer::TokenKind::Ident)) {
                        value_str = value_str ++ self.current.lexeme;
                        self.advance();
                    }
                }

                var variant = node_new(NodeKind::ExprLiteral);
                variant.name = name;
                variant.value = value_str;
                add_child(decl, variant);

                if (self.check(lexer::TokenKind::Comma)) {
                    self.advance();
                }
            } else {
                self.advance();
            }
        }
    }

    // ====================================================================
    // 9. Top-Level Declaration Parsers
    // ====================================================================

    fn parse_top_level_decl(self: *Parser) -> Node {
        var is_pub = false;
        if (self.check(lexer::TokenKind::KwPub)) {
            is_pub = true;
            self.advance();
        }

        if (self.check(lexer::TokenKind::KwConst)) {
            return self.parse_const_decl(is_pub);
        }
        if (self.check(lexer::TokenKind::KwVar)) {
            return self.parse_var_decl(is_pub);
        }
        if (self.check(lexer::TokenKind::KwFn)) {
            return self.parse_fn_decl(is_pub);
        }
        if (self.check(lexer::TokenKind::KwEnum)) {
            return self.parse_enum_decl(is_pub);
        }
        if (self.check(lexer::TokenKind::KwStruct)) {
            return self.parse_struct_decl(is_pub);
        }

        return node_new(NodeKind::Module);
    }

    fn parse_const_decl(self: *Parser, is_pub: bool) -> Node {
        var decl = node_new(NodeKind::ConstDecl);
        decl.extra_pub = is_pub;

        self.advance();

        if (self.check(lexer::TokenKind::Ident)) {
            decl.name = self.current.lexeme;
            self.advance();
        }

        if (self.check(lexer::TokenKind::Colon)) {
            self.advance();
            var type_str = "";
            if (self.check(lexer::TokenKind::LBracket)) {
                type_str = "[";
                self.advance();
                while (self.current.kind != lexer::TokenKind::RBracket 
                       and self.current.kind != lexer::TokenKind::Eof) {
                    type_str = type_str ++ self.current.lexeme;
                    self.advance();
                }
                type_str = type_str ++ "]";
                if (self.check(lexer::TokenKind::RBracket)) {
                    self.advance();
                }
            }
            if (self.check(lexer::TokenKind::Ident)) {
                type_str = type_str ++ self.current.lexeme;
                self.advance();
            }
            decl.extra_type = type_str;
        }

        if (self.check(lexer::TokenKind::Equals)) {
            self.advance();

            if (self.check(lexer::TokenKind::KwEnum)) {
                decl.kind = NodeKind::EnumDecl;
                self.advance();
                if (self.check(lexer::TokenKind::LParen)) {
                    self.advance();
                    if (self.check(lexer::TokenKind::Ident)) {
                        decl.extra_type = self.current.lexeme;
                        self.advance();
                    }
                    self.expect(lexer::TokenKind::RParen);
                }
                self.expect(lexer::TokenKind::LBrace);
                self.parse_enum_body(&decl);
                self.expect(lexer::TokenKind::RBrace);
            } else if (self.check(lexer::TokenKind::KwStruct)) {
                decl.kind = NodeKind::StructDecl;
                self.advance();
                self.expect(lexer::TokenKind::LBrace);
                self.parse_struct_body(&decl);
                self.expect(lexer::TokenKind::RBrace);
            } else if (self.check(lexer::TokenKind::Minus)) {
                self.advance();
                if (self.check(lexer::TokenKind::Number)) {
                    var val_node = node_new(NodeKind::ExprLiteral);
                    val_node.value = "-" ++ self.current.lexeme;
                    add_child(&decl, val_node);
                    self.advance();
                }
            } else if (self.check(lexer::TokenKind::Number)) {
                var val_node = node_new(NodeKind::ExprLiteral);
                val_node.value = self.current.lexeme;
                add_child(&decl, val_node);
                self.advance();
            } else if (self.check(lexer::TokenKind::Ident)) {
                var val_node = node_new(NodeKind::ExprIdentifier);
                val_node.name = self.current.lexeme;
                add_child(&decl, val_node);
                self.advance();
            } else if (self.check(lexer::TokenKind::KwTrue) or self.check(lexer::TokenKind::KwFalse)) {
                var val_node = node_new(NodeKind::ExprLiteral);
                val_node.value = self.current.lexeme;
                add_child(&decl, val_node);
                self.advance();
            } else if (self.check(lexer::TokenKind::StringLit)) {
                var val_node = node_new(NodeKind::ExprLiteral);
                val_node.value = self.current.lexeme;
                add_child(&decl, val_node);
                self.advance();
            } else {
                self.skip_to_semicolon();
                return decl;
            }

            if (self.current.kind != lexer::TokenKind::Semicolon) {
                self.skip_to_semicolon();
            }
        }

        if (self.check(lexer::TokenKind::Semicolon)) {
            self.advance();
        }
        return decl;
    }

    fn parse_var_decl(self: *Parser, is_pub: bool) -> Node {
        var decl = node_new(NodeKind::VarDecl);
        decl.extra_pub = is_pub;

        self.advance();

        if (self.check(lexer::TokenKind::Ident)) {
            decl.name = self.current.lexeme;
            self.advance();
        }

        self.skip_to_semicolon();
        return decl;
    }

    fn parse_enum_decl(self: *Parser, is_pub: bool) -> Node {
        var decl = node_new(NodeKind::EnumDecl);
        decl.extra_pub = is_pub;

        self.advance();

        if (self.check(lexer::TokenKind::Ident)) {
            decl.name = self.current.lexeme;
            self.advance();
        }

        if (self.check(lexer::TokenKind::LParen)) {
            self.advance();
            while (self.current.kind != lexer::TokenKind::RParen 
                   and self.current.kind != lexer::TokenKind::Eof) {
                self.advance();
            }
            self.expect(lexer::TokenKind::RParen);
        }

        self.expect(lexer::TokenKind::LBrace);
        self.skip_brace_body();
        self.expect(lexer::TokenKind::RBrace);

        return decl;
    }

    fn parse_struct_decl(self: *Parser, is_pub: bool) -> Node {
        var decl = node_new(NodeKind::StructDecl);
        decl.extra_pub = is_pub;

        self.advance();

        if (self.check(lexer::TokenKind::Ident)) {
            decl.name = self.current.lexeme;
            self.advance();
        }

        self.expect(lexer::TokenKind::LBrace);
        self.parse_struct_body(&decl);
        self.expect(lexer::TokenKind::RBrace);

        return decl;
    }

    fn parse_fn_decl(self: *Parser, is_pub: bool) -> Node {
        var decl = node_new(NodeKind::FnDecl);
        decl.extra_pub = is_pub;

        self.advance();

        if (self.check(lexer::TokenKind::Ident)) {
            decl.name = self.current.lexeme;
            self.advance();
            while (self.check(lexer::TokenKind::Dot)) {
                self.advance();
                if (self.check(lexer::TokenKind::Ident)) {
                    decl.name = decl.name ++ "." ++ self.current.lexeme;
                    self.advance();
                }
            }
        }

        self.expect(lexer::TokenKind::LParen);
        while (self.current.kind != lexer::TokenKind::RParen 
               and self.current.kind != lexer::TokenKind::Eof) {
            if (self.check(lexer::TokenKind::Ident)) {
                const param_name = self.current.lexeme;
                self.advance();
                if (self.check(lexer::TokenKind::Colon)) {
                    self.advance();
                }
                const param_type = self.parse_type_annotation();
            }
            if (self.check(lexer::TokenKind::Comma)) {
                self.advance();
            }
        }
        self.expect(lexer::TokenKind::RParen);

        if (self.check(lexer::TokenKind::Arrow)) {
            self.advance();
        }

        if (self.check(lexer::TokenKind::Bang)) {
            self.advance();
        }

        if (self.check(lexer::TokenKind::Ident)) {
            decl.extra_return_type = self.current.lexeme;
            self.advance();
        } else if (self.check(lexer::TokenKind::LBracket)) {
            var rt = "";
            while (self.check(lexer::TokenKind::LBracket)) {
                rt = rt ++ "[";
                self.advance();
                while (self.current.kind != lexer::TokenKind::RBracket 
                       and self.current.kind != lexer::TokenKind::Eof) {
                    rt = rt ++ self.current.lexeme;
                    self.advance();
                }
                rt = rt ++ "]";
                if (self.check(lexer::TokenKind::RBracket)) {
                    self.advance();
                }
            }
            if (self.check(lexer::TokenKind::KwConst)) {
                rt = rt ++ "const ";
                self.advance();
            }
            if (self.check(lexer::TokenKind::Star)) {
                rt = rt ++ "*";
                self.advance();
            }
            if (self.check(lexer::TokenKind::Ident)) {
                rt = rt ++ self.current.lexeme;
                self.advance();
            }
            decl.extra_return_type = rt;
        } else if (self.check(lexer::TokenKind::KwVoid)) {
            decl.extra_return_type = "void";
            self.advance();
        }

        if (self.check(lexer::TokenKind::KwConst)) {
            self.advance();
        }

        self.expect(lexer::TokenKind::LBrace);
        self.parse_fn_body();
        self.expect(lexer::TokenKind::RBrace);

        return decl;
    }

    // ====================================================================
    // 10. Module Parser
    // ====================================================================

    fn parse(self: *Parser) -> Node {
        var module = node_new(NodeKind::Module);

        if (self.check(lexer::TokenKind::KwModule)) {
            self.advance();
            if (self.check(lexer::TokenKind::Ident)) {
                module.name = self.current.lexeme;
                self.advance();
                while (self.check(lexer::TokenKind::Minus)) {
                    module.name = module.name ++ "-";
                    self.advance();
                    if (self.check(lexer::TokenKind::Ident) or self.check(lexer::TokenKind::Number)) {
                        module.name = module.name ++ self.current.lexeme;
                        self.advance();
                    }
                }
            }
            if (self.check(lexer::TokenKind::Semicolon)) {
                self.advance();
            } else if (self.check(lexer::TokenKind::LBrace)) {
                self.advance();
                self.parse_module_body(&module);
                self.expect(lexer::TokenKind::RBrace);
                return module;
            }
        }

        self.parse_module_body(&module);
        return module;
    }

    fn parse_module_body(self: *Parser, module: *Node) -> void {
        while (self.current.kind != lexer::TokenKind::Eof 
               and self.current.kind != lexer::TokenKind::RBrace) {

            if (self.check(lexer::TokenKind::KwUse) or self.check(lexer::TokenKind::KwUsing)) {
                self.advance();
                var full_path = "";
                var alias_name = "";
                if (self.check(lexer::TokenKind::Ident)) {
                    full_path = self.current.lexeme;
                    self.advance();

                    if (self.check(lexer::TokenKind::Colon) and not self.check_peek(lexer::TokenKind::Colon)) {
                        alias_name = full_path;
                        self.advance();
                        if (self.check(lexer::TokenKind::Ident)) {
                            self.advance();
                        }
                        full_path = alias_name;
                    } else {
                        while (self.check(lexer::TokenKind::Colon)) {
                            self.advance();
                            if (self.check(lexer::TokenKind::Colon)) {
                                self.advance();
                                full_path = full_path ++ "::";
                                if (self.check(lexer::TokenKind::Ident)) {
                                    full_path = full_path ++ self.current.lexeme;
                                    self.advance();
                                }
                            }
                        }
                    }
                }
                if (self.check(lexer::TokenKind::Semicolon)) {
                    self.advance();
                }
                const import_name = alias_name;
                var use_node = node_new(NodeKind::UseDecl);
                use_node.name = import_name;
                use_node.value = full_path;
                add_child(module, use_node);
                continue;
            }

            const decl = self.parse_top_level_decl();
            if (decl.kind != NodeKind::Module) {
                add_child(module, decl);
            }
        }
    }

    // ====================================================================
    // 11. Tests
    // ====================================================================

    test "kind_values" {
        assert(NodeKind::Module == 0)
        assert(NodeKind::FnDecl == 4)
        assert(NodeKind::ExprBinary == 22)
        assert(NodeKind::ExprCall == 24)
    }

    test "precedence_order" {
        const or_level = 0
        const and_level = 1
        const comp_level = 2
        const add_level = 3
        const mul_level = 4
        const unary_level = 5
        assert(or_level < and_level)
        assert(and_level < comp_level)
        assert(comp_level < add_level)
        assert(add_level < mul_level)
        assert(mul_level < unary_level)
    }

    test "max_children_constant" {
        assert(MAX_CHILDREN == 32)
    }

    test "node_kind_count" {
        assert(NodeKind::ExprReturn == 31)
        assert(NodeKind::StmtLocal == 10)
    }

    test "node_kind_coverage" {
        assert(NodeKind::Module == NodeKind::Module)
        assert(NodeKind::FnDecl != NodeKind::StructDecl)
    }

    test "expression_precedence_levels" {
        assert(10 > 9)
        assert(9 > 8)
        assert(8 > 7)
        assert(7 > 6)
        assert(6 > 5)
        assert(5 > 4)
        assert(4 > 3)
        assert(3 > 2)
        assert(2 > 1)
        assert(1 > 0)
    }

    test "break_continue_node_kinds" {
        assert(NodeKind::StmtBreak == 17)
        assert(NodeKind::StmtContinue == 18)
        assert(NodeKind::StmtBreak != NodeKind::StmtContinue)
    }

    test "error_recovery_skip_to_semicolon" {
        var p = parser_init("fn foo() { x; }", 16);
        assert(p.current.kind != lexer::TokenKind::Eof)
    }

    test "struct_decl_distinct_from_enum" {
        assert(NodeKind::StructDecl == 6)
        assert(NodeKind::EnumDecl == 5)
        assert(NodeKind::StructDecl != NodeKind::EnumDecl)
    }

    test "all_statement_kinds_unique" {
        assert(NodeKind::StmtLocal != NodeKind::StmtAssign)
        assert(NodeKind::StmtAssign != NodeKind::StmtIf)
        assert(NodeKind::StmtIf != NodeKind::StmtWhile)
        assert(NodeKind::StmtWhile != NodeKind::StmtFor)
        assert(NodeKind::StmtFor != NodeKind::StmtExpr)
        assert(NodeKind::StmtExpr != NodeKind::ExprReturn)
        assert(NodeKind::ExprReturn != NodeKind::StmtBreak)
        assert(NodeKind::StmtBreak != NodeKind::StmtContinue)
    }
}

// SPDX-License-Identifier: Apache-2.0
module Lexing {
    use base::types;

    enum TokenKind {
        KwPub = 0, KwConst = 1, KwFn = 2, KwEnum = 3, KwStruct = 4,
        KwTest = 5, KwInvariant = 6, KwBench = 7, KwModule = 8,
        KwIf = 9, KwElse = 10, KwFor = 11, KwWhile = 12, KwSwitch = 13,
        KwReturn = 14, KwVar = 15, KwUsing = 16, KwVoid = 17,
        KwTrue = 18, KwFalse = 19, KwUse = 20, KwOr = 21, KwAnd = 22,
        KwTry = 23, KwBreak = 24, KwContinue = 25,

        Ident = 30, Number = 31, StringLit = 32, CharLiteral = 33,

        Plus = 40, Minus = 41, Star = 42, Slash = 43, Percent = 44,
        Amp = 45, Pipe = 46, Caret = 47, Tilde = 48,

        Lt = 50, Gt = 51, Lte = 52, Gte = 53, Eq = 54, Neq = 55,

        Colon = 60, Comma = 61, Equals = 62, LParen = 63, RParen = 64,
        LBrace = 65, RBrace = 66, LBracket = 67, RBracket = 68,
        Dot = 69, Bang = 70, Semicolon = 71,

        Arrow = 80, FatArrow = 81, Power = 82, DotDot = 83, PlusPlus = 84,
        ShiftLeft = 85, ShiftRight = 86, PlusEquals = 87, PlusPercent = 88,

        Eof = 255,
    }

    struct Token {
        kind: TokenKind;
        lexeme: [256]u8;
        lexeme_len: u32;
        line: u32;
        col: u32;
    }

    struct Lexer {
        source: [65536]u8;
        source_len: u32;
        pos: u32;
        line: u32;
        col: u32;
    }

    fn lexer_init(src: [65536]u8, len: u32) -> Lexer {
        return Lexer{
            source = src,
            source_len = len,
            pos = 0,
            line = 1,
            col = 1,
        };
    }

    fn peek(lex: Lexer) -> u8 {
        if (lex.pos >= lex.source_len) {
            return 0;
        }
        return lex.source[lex.pos];
    }

    fn peek_offset(lex: Lexer, offset: u32) -> u8 {
        const new_pos = lex.pos + offset;
        if (new_pos >= lex.source_len) {
            return 0;
        }
        return lex.source[new_pos];
    }

    fn advance(lex: Lexer) -> Lexer {
        var new_lex = lex;
        const ch = peek(lex);
        if (ch == 10) {
            new_lex.line = lex.line + 1;
            new_lex.col = 1;
        } else {
            new_lex.col = lex.col + 1;
        }
        new_lex.pos = lex.pos + 1;
        return new_lex;
    }

    fn is_alpha(ch: u8) -> bool {
        return (ch >= 65 and ch <= 90) or (ch >= 97 and ch <= 122) or (ch == 95);
    }

    fn is_digit(ch: u8) -> bool {
        return ch >= 48 and ch <= 57;
    }

    fn is_hex_digit(ch: u8) -> bool {
        return (ch >= 48 and ch <= 57) or (ch >= 65 and ch <= 70) or (ch >= 97 and ch <= 102);
    }

    fn is_alnum(ch: u8) -> bool {
        return is_alpha(ch) or is_digit(ch);
    }

    fn is_whitespace(ch: u8) -> bool {
        return ch == 32 or ch == 9 or ch == 10 or ch == 13;
    }

    fn skip_whitespace_and_comments(lex: Lexer) -> Lexer {
        var l = lex;
        var done = false;
        while (done == false) {
            while (l.pos < l.source_len and is_whitespace(peek(l))) {
                l = advance(l);
            }

            if (l.pos + 1 < l.source_len and l.source[l.pos] == 47 and l.source[l.pos + 1] == 47) {
                while (l.pos < l.source_len and peek(l) != 10) {
                    l = advance(l);
                }
            } else if (l.pos + 1 < l.source_len and l.source[l.pos] == 47 and l.source[l.pos + 1] == 42) {
                l = advance(l);
                l = advance(l);
                var depth: u32 = 1;
                while (depth > 0 and l.pos < l.source_len) {
                    if (l.pos + 1 < l.source_len and l.source[l.pos] == 42 and l.source[l.pos + 1] == 47) {
                        l = advance(l);
                        l = advance(l);
                        depth = depth - 1;
                    } else if (l.pos + 1 < l.source_len and l.source[l.pos] == 47 and l.source[l.pos + 1] == 42) {
                        l = advance(l);
                        l = advance(l);
                        depth = depth + 1;
                    } else {
                        l = advance(l);
                    }
                }
            } else {
                done = true;
            }
        }
        return l;
    }

    fn lexeme_equals(lexeme: [256]u8, len: u32, target: str) -> bool {
        var i: u32 = 0;
        while (i < len) {
            if (lexeme[i] != target[i]) {
                return false;
            }
            i = i + 1;
        }
        return true;
    }

    fn check_keyword(lexeme: [256]u8, len: u32) -> TokenKind {
        if (len == 2) {
            if (lexeme[0] == 102 and lexeme[1] == 110) { return TokenKind::KwFn; }
            if (lexeme[0] == 105 and lexeme[1] == 102) { return TokenKind::KwIf; }
            if (lexeme[0] == 111 and lexeme[1] == 114) { return TokenKind::KwOr; }
            return TokenKind::Ident;
        }
        if (len == 3) {
            if (lexeme[0] == 112 and lexeme[1] == 117 and lexeme[2] == 98) { return TokenKind::KwPub; }
            if (lexeme[0] == 118 and lexeme[1] == 97 and lexeme[2] == 114) { return TokenKind::KwVar; }
            if (lexeme[0] == 116 and lexeme[1] == 114 and lexeme[2] == 121) { return TokenKind::KwTry; }
            if (lexeme[0] == 117 and lexeme[1] == 115 and lexeme[2] == 101) { return TokenKind::KwUse; }
            if (lexeme[0] == 97 and lexeme[1] == 110 and lexeme[2] == 100) { return TokenKind::KwAnd; }
            if (lexeme[0] == 102 and lexeme[1] == 111 and lexeme[2] == 114) { return TokenKind::KwFor; }
            return TokenKind::Ident;
        }
        if (len == 4) {
            if (lexeme[0] == 101 and lexeme[1] == 108 and lexeme[2] == 115 and lexeme[3] == 101) { return TokenKind::KwElse; }
            if (lexeme[0] == 101 and lexeme[1] == 110 and lexeme[2] == 117 and lexeme[3] == 109) { return TokenKind::KwEnum; }
            if (lexeme[0] == 116 and lexeme[1] == 114 and lexeme[2] == 117 and lexeme[3] == 101) { return TokenKind::KwTrue; }
            if (lexeme[0] == 118 and lexeme[1] == 111 and lexeme[2] == 105 and lexeme[3] == 100) { return TokenKind::KwVoid; }
            if (lexeme[0] == 116 and lexeme[1] == 101 and lexeme[2] == 115 and lexeme[3] == 116) { return TokenKind::KwTest; }
            return TokenKind::Ident;
        }
        if (len == 5) {
            if (lexeme[0] == 99 and lexeme[1] == 111 and lexeme[2] == 110 and lexeme[3] == 115 and lexeme[4] == 116) { return TokenKind::KwConst; }
            if (lexeme[0] == 119 and lexeme[1] == 104 and lexeme[2] == 105 and lexeme[3] == 108 and lexeme[4] == 101) { return TokenKind::KwWhile; }
            if (lexeme[0] == 117 and lexeme[1] == 115 and lexeme[2] == 105 and lexeme[3] == 110 and lexeme[4] == 103) { return TokenKind::KwUsing; }
            if (lexeme[0] == 102 and lexeme[1] == 97 and lexeme[2] == 108 and lexeme[3] == 115 and lexeme[4] == 101) { return TokenKind::KwFalse; }
            if (lexeme[0] == 98 and lexeme[1] == 114 and lexeme[2] == 101 and lexeme[3] == 97 and lexeme[4] == 107) { return TokenKind::KwBreak; }
            return TokenKind::Ident;
        }
        if (len == 6) {
            if (lexeme[0] == 115 and lexeme[1] == 116 and lexeme[2] == 114 and lexeme[3] == 117 and lexeme[4] == 99 and lexeme[5] == 116) { return TokenKind::KwStruct; }
            if (lexeme[0] == 114 and lexeme[1] == 101 and lexeme[2] == 116 and lexeme[3] == 117 and lexeme[4] == 114 and lexeme[5] == 110) { return TokenKind::KwReturn; }
            if (lexeme[0] == 115 and lexeme[1] == 119 and lexeme[2] == 105 and lexeme[3] == 116 and lexeme[4] == 99 and lexeme[5] == 104) { return TokenKind::KwSwitch; }
            if (lexeme[0] == 109 and lexeme[1] == 111 and lexeme[2] == 100 and lexeme[3] == 117 and lexeme[4] == 108 and lexeme[5] == 101) { return TokenKind::KwModule; }
            return TokenKind::Ident;
        }
        if (len == 8) {
            if (lexeme[0] == 99 and lexeme[1] == 111 and lexeme[2] == 110
                and lexeme[3] == 116 and lexeme[4] == 105 and lexeme[5] == 110
                and lexeme[6] == 117 and lexeme[7] == 101) { return TokenKind::KwContinue; }
            return TokenKind::Ident;
        }
        if (len == 9) {
            if (lexeme[0] == 105 and lexeme[1] == 110 and lexeme[2] == 118
                and lexeme[3] == 97 and lexeme[4] == 114 and lexeme[5] == 105
                and lexeme[6] == 97 and lexeme[7] == 110 and lexeme[8] == 116) { return TokenKind::KwInvariant; }
            return TokenKind::Ident;
        }
        if (len == 5) {
            if (lexeme[0] == 98 and lexeme[1] == 101 and lexeme[2] == 110 and lexeme[3] == 99 and lexeme[4] == 104) { return TokenKind::KwBench; }
            return TokenKind::Ident;
        }
        return TokenKind::Ident;
    }

    fn make_token_simple(kind: TokenKind, line: u32, col: u32, text: str, text_len: u32) -> Token {
        var tok = Token{
            kind = kind,
            lexeme = [0; 256],
            lexeme_len = text_len,
            line = line,
            col = col,
        };
        var i: u32 = 0;
        while (i < text_len) {
            tok.lexeme[i] = text[i];
            i = i + 1;
        }
        return tok;
    }

    fn make_token_from_source(lex: Lexer, kind: TokenKind, start_pos: u32, start_line: u32, start_col: u32) -> Token {
        var tok = Token{
            kind = kind,
            lexeme = [0; 256],
            lexeme_len = lex.pos - start_pos,
            line = start_line,
            col = start_col,
        };
        var i: u32 = 0;
        while (i < tok.lexeme_len) {
            tok.lexeme[i] = lex.source[start_pos + i];
            i = i + 1;
        }
        return tok;
    }

    fn scan_identifier(lex: Lexer) -> Token {
        const start_line = lex.line;
        const start_col = lex.col;
        const start_pos = lex.pos;
        var l = lex;

        while (l.pos < l.source_len) {
            const ch = peek(l);
            if (is_alnum(ch) or ch == 95 or ch == 64) {
                l = advance(l);
            } else {
                break;
            }
        }

        var tok = make_token_from_source(l, TokenKind::Ident, start_pos, start_line, start_col);
        tok.kind = check_keyword(tok.lexeme, tok.lexeme_len);
        return tok;
    }

    fn scan_number(lex: Lexer) -> Token {
        const start_line = lex.line;
        const start_col = lex.col;
        const start_pos = lex.pos;
        var l = lex;
        var is_hex = false;

        while (l.pos < l.source_len) {
            const ch = peek(l);
            if (is_hex_digit(ch) or ch == 95) {
                if (ch == 120 or ch == 88) {
                    is_hex = true;
                }
                l = advance(l);
            } else if (ch == 46) {
                const next_ch = peek_offset(l, 1);
                if (next_ch == 46) {
                    break;
                }
                l = advance(l);
            } else if (ch == 98 or ch == 66) {
                l = advance(l);
                break;
            } else {
                break;
            }
        }

        return make_token_from_source(l, TokenKind::Number, start_pos, start_line, start_col);
    }

    fn scan_string(lex: Lexer) -> Token {
        const start_line = lex.line;
        const start_col = lex.col;
        var l = lex;
        l = advance(l);

        var tok = Token{
            kind = TokenKind::StringLit,
            lexeme = [0; 256],
            lexeme_len = 0,
            line = start_line,
            col = start_col,
        };

        while (l.pos < l.source_len and peek(l) != 34) {
            if (peek(l) == 92) {
                l = advance(l);
                if (l.pos < l.source_len) {
                    const escaped = peek(l);
                    if (escaped == 110) {
                        tok.lexeme[tok.lexeme_len] = 10;
                    } else if (escaped == 116) {
                        tok.lexeme[tok.lexeme_len] = 9;
                    } else if (escaped == 92) {
                        tok.lexeme[tok.lexeme_len] = 92;
                    } else if (escaped == 34) {
                        tok.lexeme[tok.lexeme_len] = 34;
                    } else {
                        tok.lexeme[tok.lexeme_len] = 92;
                        tok.lexeme_len = tok.lexeme_len + 1;
                        tok.lexeme[tok.lexeme_len] = escaped;
                    }
                    tok.lexeme_len = tok.lexeme_len + 1;
                    l = advance(l);
                }
            } else {
                tok.lexeme[tok.lexeme_len] = peek(l);
                tok.lexeme_len = tok.lexeme_len + 1;
                l = advance(l);
            }
        }

        if (l.pos < l.source_len) {
            l = advance(l);
        }

        return tok;
    }

    fn scan_char(lex: Lexer) -> Token {
        const start_line = lex.line;
        const start_col = lex.col;
        var l = lex;
        l = advance(l);

        var tok = Token{
            kind = TokenKind::CharLiteral,
            lexeme = [0; 256],
            lexeme_len = 0,
            line = start_line,
            col = start_col,
        };

        if (l.pos < l.source_len) {
            if (peek(l) == 92) {
                tok.lexeme[0] = 92;
                tok.lexeme_len = 1;
                l = advance(l);
                if (l.pos < l.source_len) {
                    tok.lexeme[1] = peek(l);
                    tok.lexeme_len = 2;
                    l = advance(l);
                }
            } else {
                tok.lexeme[0] = peek(l);
                tok.lexeme_len = 1;
                l = advance(l);
            }
        }

        if (l.pos < l.source_len and peek(l) == 39) {
            l = advance(l);
        }

        return tok;
    }

    fn next_token(lex: Lexer) -> (Lexer, Token) {
        var l = skip_whitespace_and_comments(lex);

        const start_line = l.line;
        const start_col = l.col;
        const start_pos = l.pos;

        if (l.pos >= l.source_len) {
            return (l, make_token_simple(TokenKind::Eof, start_line, start_col, "", 0));
        }

        const ch = peek(l);

        if (ch == 59) {
            l = advance(l);
            return (l, make_token_simple(TokenKind::Semicolon, start_line, start_col, ";", 1));
        }

        if (l.pos + 1 < l.source_len) {
            const next = l.source[l.pos + 1];

            if (ch == 45 and next == 62) {
                l = advance(l); l = advance(l);
                return (l, make_token_simple(TokenKind::Arrow, start_line, start_col, "->", 2));
            }
            if (ch == 61 and next == 62) {
                l = advance(l); l = advance(l);
                return (l, make_token_simple(TokenKind::FatArrow, start_line, start_col, "=>", 2));
            }
            if (ch == 42 and next == 42) {
                l = advance(l); l = advance(l);
                return (l, make_token_simple(TokenKind::Power, start_line, start_col, "**", 2));
            }
            if (ch == 60 and next == 61) {
                l = advance(l); l = advance(l);
                return (l, make_token_simple(TokenKind::Lte, start_line, start_col, "<=", 2));
            }
            if (ch == 62 and next == 61) {
                l = advance(l); l = advance(l);
                return (l, make_token_simple(TokenKind::Gte, start_line, start_col, ">=", 2));
            }
            if (ch == 61 and next == 61) {
                l = advance(l); l = advance(l);
                return (l, make_token_simple(TokenKind::Eq, start_line, start_col, "==", 2));
            }
            if (ch == 33 and next == 61) {
                l = advance(l); l = advance(l);
                return (l, make_token_simple(TokenKind::Neq, start_line, start_col, "!=", 2));
            }
            if (ch == 60 and next == 60) {
                l = advance(l); l = advance(l);
                return (l, make_token_simple(TokenKind::ShiftLeft, start_line, start_col, "<<", 2));
            }
            if (ch == 62 and next == 62) {
                l = advance(l); l = advance(l);
                return (l, make_token_simple(TokenKind::ShiftRight, start_line, start_col, ">>", 2));
            }
            if (ch == 43 and next == 43) {
                l = advance(l); l = advance(l);
                return (l, make_token_simple(TokenKind::PlusPlus, start_line, start_col, "++", 2));
            }
            if (ch == 43 and next == 61) {
                l = advance(l); l = advance(l);
                return (l, make_token_simple(TokenKind::PlusEquals, start_line, start_col, "+=", 2));
            }
            if (ch == 43 and next == 37) {
                l = advance(l); l = advance(l);
                return (l, make_token_simple(TokenKind::PlusPercent, start_line, start_col, "+%", 2));
            }
            if (ch == 46 and next == 46) {
                l = advance(l); l = advance(l);
                return (l, make_token_simple(TokenKind::DotDot, start_line, start_col, "..", 2));
            }
        }

        if (ch == 58) { l = advance(l); return (l, make_token_simple(TokenKind::Colon, start_line, start_col, ":", 1)); }
        if (ch == 44) { l = advance(l); return (l, make_token_simple(TokenKind::Comma, start_line, start_col, ",", 1)); }
        if (ch == 61) { l = advance(l); return (l, make_token_simple(TokenKind::Equals, start_line, start_col, "=", 1)); }
        if (ch == 40) { l = advance(l); return (l, make_token_simple(TokenKind::LParen, start_line, start_col, "(", 1)); }
        if (ch == 41) { l = advance(l); return (l, make_token_simple(TokenKind::RParen, start_line, start_col, ")", 1)); }
        if (ch == 123) { l = advance(l); return (l, make_token_simple(TokenKind::LBrace, start_line, start_col, "{", 1)); }
        if (ch == 125) { l = advance(l); return (l, make_token_simple(TokenKind::RBrace, start_line, start_col, "}", 1)); }
        if (ch == 91) { l = advance(l); return (l, make_token_simple(TokenKind::LBracket, start_line, start_col, "[", 1)); }
        if (ch == 93) { l = advance(l); return (l, make_token_simple(TokenKind::RBracket, start_line, start_col, "]", 1)); }
        if (ch == 46) { l = advance(l); return (l, make_token_simple(TokenKind::Dot, start_line, start_col, ".", 1)); }
        if (ch == 33) { l = advance(l); return (l, make_token_simple(TokenKind::Bang, start_line, start_col, "!", 1)); }
        if (ch == 43) { l = advance(l); return (l, make_token_simple(TokenKind::Plus, start_line, start_col, "+", 1)); }
        if (ch == 45) { l = advance(l); return (l, make_token_simple(TokenKind::Minus, start_line, start_col, "-", 1)); }
        if (ch == 42) { l = advance(l); return (l, make_token_simple(TokenKind::Star, start_line, start_col, "*", 1)); }
        if (ch == 47) { l = advance(l); return (l, make_token_simple(TokenKind::Slash, start_line, start_col, "/", 1)); }
        if (ch == 37) { l = advance(l); return (l, make_token_simple(TokenKind::Percent, start_line, start_col, "%", 1)); }
        if (ch == 38) { l = advance(l); return (l, make_token_simple(TokenKind::Amp, start_line, start_col, "&", 1)); }
        if (ch == 124) { l = advance(l); return (l, make_token_simple(TokenKind::Pipe, start_line, start_col, "|", 1)); }
        if (ch == 94) { l = advance(l); return (l, make_token_simple(TokenKind::Caret, start_line, start_col, "^", 1)); }
        if (ch == 126) { l = advance(l); return (l, make_token_simple(TokenKind::Tilde, start_line, start_col, "~", 1)); }
        if (ch == 60) { l = advance(l); return (l, make_token_simple(TokenKind::Lt, start_line, start_col, "<", 1)); }
        if (ch == 62) { l = advance(l); return (l, make_token_simple(TokenKind::Gt, start_line, start_col, ">", 1)); }

        if (is_alpha(ch) or ch == 95 or ch == 64) {
            const tok = scan_identifier(l);
            l.pos = start_pos + tok.lexeme_len;
            return (l, tok);
        }

        if (is_digit(ch)) {
            const tok = scan_number(l);
            return (l, tok);
        }

        if (ch == 34) {
            const tok = scan_string(l);
            return (l, tok);
        }

        if (ch == 39) {
            const tok = scan_char(l);
            return (l, tok);
        }

        l = advance(l);
        return (l, make_token_simple(TokenKind::Eof, start_line, start_col, "", 0));
    }

    test is_alpha_lowercase
        given result = is_alpha(97)
        then result == true

    test is_alpha_uppercase
        given result = is_alpha(65)
        then result == true

    test is_alpha_underscore
        given result = is_alpha(95)
        then result == true

    test is_digit_zero
        given result = is_digit(48)
        then result == true

    test is_digit_nine
        given result = is_digit(57)
        then result == true

    test is_whitespace_space
        given result = is_whitespace(32)
        then result == true

    test is_whitespace_tab
        given result = is_whitespace(9)
        then result == true

    test is_whitespace_newline
        given result = is_whitespace(10)
        then result == true

    test keyword_fn
        given lexeme = "fn"
        given result = check_keyword(lexeme, 2)
        then result == TokenKind::KwFn

    test keyword_const
        given lexeme = "const"
        given result = check_keyword(lexeme, 5)
        then result == TokenKind::KwConst

    test keyword_struct
        given lexeme = "struct"
        given result = check_keyword(lexeme, 6)
        then result == TokenKind::KwStruct

    test keyword_return
        given lexeme = "return"
        given result = check_keyword(lexeme, 6)
        then result == TokenKind::KwReturn

    test keyword_invariant
        given lexeme = "invariant"
        given result = check_keyword(lexeme, 9)
        then result == TokenKind::KwInvariant

    test keyword_break
        given lexeme = "break"
        given result = check_keyword(lexeme, 5)
        then result == TokenKind::KwBreak

    test keyword_continue
        given lexeme = "continue"
        given result = check_keyword(lexeme, 8)
        then result == TokenKind::KwContinue

    test identifier_not_keyword
        given lexeme = "hello"
        given result = check_keyword(lexeme, 5)
        then result == TokenKind::Ident

    invariant eof_is_255
        assert TokenKind::Eof == 255

    invariant keyword_count_is_26
        assert TokenKind::KwContinue == 25

    invariant total_token_kinds
        assert TokenKind::Eof == 255
}

// SPDX-License-Identifier: Apache-2.0
module Stdlib {
    use compiler::parser;
    use compiler::lexer;

    enum StdlibResult {
        Ok,
        Err,
        Empty,
    }

    struct Vec {
        data: [256]u8;
        len: u32;
        capacity: u32;
    }

    struct Str {
        data: [4096]u8;
        len: u32;
    }

    struct Map {
        keys: [64]Str;
        values: [64]Str;
        count: u32;
    }

    struct Opt {
        has_value: bool;
        value: u64;
    }

    struct Result {
        is_ok: bool;
        value: u64;
        error_code: u32;
    }

    struct Iterator {
        data: [256]u8;
        data_len: u32;
        pos: u32;
    }

    const DEFAULT_CAPACITY: u32 = 16;
    const MAX_MAP_ENTRIES: u32 = 64;
    const MAX_STRING_LEN: u32 = 4096;

    fn vec_new() -> Vec {
        return Vec{ data = [0; 256], len = 0, capacity = DEFAULT_CAPACITY };
    }

    fn vec_with_capacity(cap: u32) -> Vec {
        return Vec{ data = [0; 256], len = 0, capacity = cap };
    }

    fn vec_push(v: *Vec, val: u8) -> StdlibResult {
        if (v.len >= v.capacity) {
            return StdlibResult::Err;
        }
        v.data[v.len] = val;
        v.len = v.len + 1;
        return StdlibResult::Ok;
    }

    fn vec_pop(v: *Vec) -> u8 {
        if (v.len == 0) {
            return 0;
        }
        v.len = v.len - 1;
        return v.data[v.len];
    }

    fn vec_get(v: Vec, idx: u32) -> u8 {
        if (idx >= v.len) {
            return 0;
        }
        return v.data[idx];
    }

    fn vec_set(v: *Vec, idx: u32, val: u8) -> StdlibResult {
        if (idx >= v.len) {
            return StdlibResult::Err;
        }
        v.data[idx] = val;
        return StdlibResult::Ok;
    }

    fn vec_len(v: Vec) -> u32 {
        return v.len;
    }

    fn vec_clear(v: *Vec) -> void {
        v.len = 0;
    }

    fn vec_is_empty(v: Vec) -> bool {
        return v.len == 0;
    }

    fn vec_contains(v: Vec, val: u8) -> bool {
        var i: u32 = 0;
        while (i < v.len) {
            if (v.data[i] == val) {
                return true;
            }
            i = i + 1;
        }
        return false;
    }

    fn vec_index_of(v: Vec, val: u8) -> i32 {
        var i: u32 = 0;
        while (i < v.len) {
            if (v.data[i] == val) {
                return i as i32;
            }
            i = i + 1;
        }
        return -1;
    }

    fn vec_reverse(v: *Vec) -> void {
        var i: u32 = 0;
        var j: u32 = v.len;
        while (i < j) {
            j = j - 1;
            var tmp = v.data[i];
            v.data[i] = v.data[j];
            v.data[j] = tmp;
            i = i + 1;
        }
    }

    fn str_new() -> Str {
        return Str{ data = [0; 4096], len = 0 };
    }

    fn str_from(raw: str, raw_len: u32) -> Str {
        var s = Str{ data = [0; 4096], len = raw_len };
        var i: u32 = 0;
        while (i < raw_len and i < MAX_STRING_LEN) {
            s.data[i] = raw[i];
            i = i + 1;
        }
        s.len = i;
        return s;
    }

    fn str_len(s: Str) -> u32 {
        return s.len;
    }

    fn str_is_empty(s: Str) -> bool {
        return s.len == 0;
    }

    fn str_eq(a: Str, b: Str) -> bool {
        if (a.len != b.len) {
            return false;
        }
        var i: u32 = 0;
        while (i < a.len) {
            if (a.data[i] != b.data[i]) {
                return false;
            }
            i = i + 1;
        }
        return true;
    }

    fn str_concat(a: Str, b: Str) -> Str {
        var result = Str{ data = [0; 4096], len = 0 };
        var i: u32 = 0;
        while (i < a.len and result.len < MAX_STRING_LEN) {
            result.data[result.len] = a.data[i];
            result.len = result.len + 1;
            i = i + 1;
        }
        i = 0;
        while (i < b.len and result.len < MAX_STRING_LEN) {
            result.data[result.len] = b.data[i];
            result.len = result.len + 1;
            i = i + 1;
        }
        return result;
    }

    fn str_char_at(s: Str, idx: u32) -> u8 {
        if (idx >= s.len) {
            return 0;
        }
        return s.data[idx];
    }

    fn str_contains(s: Str, ch: u8) -> bool {
        var i: u32 = 0;
        while (i < s.len) {
            if (s.data[i] == ch) {
                return true;
            }
            i = i + 1;
        }
        return false;
    }

    fn str_index_of(s: Str, ch: u8) -> i32 {
        var i: u32 = 0;
        while (i < s.len) {
            if (s.data[i] == ch) {
                return i as i32;
            }
            i = i + 1;
        }
        return -1;
    }

    fn str_sub(s: Str, start: u32, length: u32) -> Str {
        var result = Str{ data = [0; 4096], len = 0 };
        var i: u32 = 0;
        while (i < length and start + i < s.len and result.len < MAX_STRING_LEN) {
            result.data[result.len] = s.data[start + i];
            result.len = result.len + 1;
            i = i + 1;
        }
        return result;
    }

    fn map_new() -> Map {
        return Map{
            keys = [Str{ data = [0; 4096], len = 0 }; MAX_MAP_ENTRIES],
            values = [Str{ data = [0; 4096], len = 0 }; MAX_MAP_ENTRIES],
            count = 0,
        };
    }

    fn map_insert(m: *Map, key: Str, val: Str) -> StdlibResult {
        var i: u32 = 0;
        while (i < m.count) {
            if (str_eq(m.keys[i], key)) {
                m.values[i] = val;
                return StdlibResult::Ok;
            }
            i = i + 1;
        }
        if (m.count >= MAX_MAP_ENTRIES) {
            return StdlibResult::Err;
        }
        m.keys[m.count] = key;
        m.values[m.count] = val;
        m.count = m.count + 1;
        return StdlibResult::Ok;
    }

    fn map_get(m: Map, key: Str) -> Opt {
        var i: u32 = 0;
        while (i < m.count) {
            if (str_eq(m.keys[i], key)) {
                return Opt{ has_value = true, value = 0 };
            }
            i = i + 1;
        }
        return Opt{ has_value = false, value = 0 };
    }

    fn map_contains(m: Map, key: Str) -> bool {
        var i: u32 = 0;
        while (i < m.count) {
            if (str_eq(m.keys[i], key)) {
                return true;
            }
            i = i + 1;
        }
        return false;
    }

    fn map_len(m: Map) -> u32 {
        return m.count;
    }

    fn opt_some(val: u64) -> Opt {
        return Opt{ has_value = true, value = val };
    }

    fn opt_none() -> Opt {
        return Opt{ has_value = false, value = 0 };
    }

    fn opt_is_some(o: Opt) -> bool {
        return o.has_value;
    }

    fn opt_is_none(o: Opt) -> bool {
        return o.has_value == false;
    }

    fn opt_unwrap(o: Opt) -> u64 {
        return o.value;
    }

    fn opt_unwrap_or(o: Opt, default: u64) -> u64 {
        if (o.has_value) {
            return o.value;
        }
        return default;
    }

    fn result_ok(val: u64) -> Result {
        return Result{ is_ok = true, value = val, error_code = 0 };
    }

    fn result_err(code: u32) -> Result {
        return Result{ is_ok = false, value = 0, error_code = code };
    }

    fn result_is_ok(r: Result) -> bool {
        return r.is_ok;
    }

    fn result_is_err(r: Result) -> bool {
        return r.is_ok == false;
    }

    fn result_unwrap(r: Result) -> u64 {
        return r.value;
    }

    fn result_unwrap_or(r: Result, default: u64) -> u64 {
        if (r.is_ok) {
            return r.value;
        }
        return default;
    }

    fn result_error_code(r: Result) -> u32 {
        return r.error_code;
    }

    fn iter_new(data: [256]u8, len: u32) -> Iterator {
        return Iterator{ data = data, data_len = len, pos = 0 };
    }

    fn iter_has_next(it: Iterator) -> bool {
        return it.pos < it.data_len;
    }

    fn iter_next(it: *Iterator) -> u8 {
        if (it.pos >= it.data_len) {
            return 0;
        }
        var val = it.data[it.pos];
        it.pos = it.pos + 1;
        return val;
    }

    fn iter_peek(it: Iterator) -> u8 {
        if (it.pos >= it.data_len) {
            return 0;
        }
        return it.data[it.pos];
    }

    fn iter_pos(it: Iterator) -> u32 {
        return it.pos;
    }

    fn iter_remaining(it: Iterator) -> u32 {
        if (it.pos >= it.data_len) {
            return 0;
        }
        return it.data_len - it.pos;
    }

    fn fmt_u32(val: u32) -> Str {
        if (val == 0) {
            var s = str_new();
            s.data[0] = 48;
            s.len = 1;
            return s;
        }
        var buf: [16]u8;
        var pos: u32 = 16;
        var n = val;
        while (n > 0) {
            pos = pos - 1;
            buf[pos] = 48 + (n % 10) as u8;
            n = n / 10;
        }
        var result = str_new();
        var i: u32 = pos;
        while (i < 16) {
            result.data[result.len] = buf[i];
            result.len = result.len + 1;
            i = i + 1;
        }
        return result;
    }

    fn fmt_i32(val: i32) -> Str {
        if (val < 0) {
            var result = str_new();
            result.data[0] = 45;
            result.len = 1;
            var uval = (0 - val) as u32;
            var digits = fmt_u32(uval);
            var i: u32 = 0;
            while (i < digits.len and result.len < MAX_STRING_LEN) {
                result.data[result.len] = digits.data[i];
                result.len = result.len + 1;
                i = i + 1;
            }
            return result;
        }
        return fmt_u32(val as u32);
    }

    fn fmt_bool(val: bool) -> Str {
        if (val) {
            var s = str_new();
            s.data[0] = 116; s.data[1] = 114; s.data[2] = 117; s.data[3] = 101;
            s.len = 4;
            return s;
        }
        var s = str_new();
        s.data[0] = 102; s.data[1] = 97; s.data[2] = 108; s.data[3] = 115; s.data[4] = 101;
        s.len = 5;
        return s;
    }

    fn fmt_hex(val: u32) -> Str {
        var hex_chars: [16]u8;
        hex_chars[0] = 48; hex_chars[1] = 49; hex_chars[2] = 50; hex_chars[3] = 51;
        hex_chars[4] = 52; hex_chars[5] = 53; hex_chars[6] = 54; hex_chars[7] = 55;
        hex_chars[8] = 56; hex_chars[9] = 57; hex_chars[10] = 97; hex_chars[11] = 98;
        hex_chars[12] = 99; hex_chars[13] = 100; hex_chars[14] = 101; hex_chars[15] = 102;
        var result = str_new();
        if (val == 0) {
            result.data[0] = 48; result.data[1] = 120; result.data[2] = 48;
            result.len = 3;
            return result;
        }
        result.data[0] = 48; result.data[1] = 120;
        result.len = 2;
        var started: bool = false;
        var shift: i32 = 28;
        while (shift >= 0) {
            var nibble = (val >> shift) as u32 and 15;
            if (nibble != 0 or started) {
                result.data[result.len] = hex_chars[nibble];
                result.len = result.len + 1;
                started = true;
            }
            shift = shift - 4;
        }
        return result;
    }

