// SPDX-License-Identifier: Apache-2.0
// runtime/process.t27 — Runtime Process Specification
// Process spawning, termination, piping, PTY
// φ² + 1/φ² = 3 | TRINITY

module runtime-process;

// ============================================================================
// Imports
// ============================================================================

use std;

// ============================================================================
// Constants
// ============================================================================

/// Default process spawn timeout in milliseconds
pub const SPAWN_TIMEOUT_MS : u32 = 5000;  // 5 seconds

/// Default PTY size in columns
pub const PTY_COLS_DEFAULT : u16 = 80;

/// Default PTY size in rows
pub const PTY_ROWS_DEFAULT : u16 = 24;

/// Maximum pipe buffer size in bytes
pub const MAX_PIPE_BUFFER : u32 = 65536;  // 64KB

/// Process signal types
pub const ProcessSignal = enum(u8) {
    terminate = 0,   // SIGTERM
    kill = 1,        // SIGKILL
    interrupt = 2,    // SIGINT
    hangup = 3,       // SIGHUP
    stop = 4,         // SIGSTOP
    continue = 5,     // SIGCONT
};

/// Process state
pub const ProcessState = enum(u8) {
    not_started = 0,
    running = 1,
    stopped = 2,
    terminated = 3,
    zombie = 4,       // Exited but not reaped
};

/// PTY mode
pub const PTYMode = enum(u8) {
    raw = 0,
    cooked = 1,
    echo = 2,
};

// ============================================================================
// Types
// ============================================================================

/// Process identifier
pub const ProcessID = u32;

/// Process information
pub const ProcessInfo = struct {
    pid : ProcessID,
    name : []u8,
    command : []u8,
    args : [][]u8,
    state : ProcessState,
    exit_code : ?u8,
};

/// Spawn options
pub const SpawnOptions = struct {
    env : [][]u8,      // Environment variables (KEY=VALUE)
    cwd : ?[]u8,        // Working directory
    timeout_ms : u32,
    detached : bool,
    pty_enabled : bool,
    pty_cols : u16,
    pty_rows : u16,
};

/// Pipe configuration
pub const PipeConfig = struct {
    stdin : []u8,       // Input data
    stdout_max : u32,   // Max bytes to capture
    stderr_max : u32,   // Max bytes to capture
    merge_output : bool,  // Merge stderr into stdout
};

/// Process spawn result
pub const SpawnResult = struct {
    pid : ProcessID,
    success : bool,
    error_message : ?[]u8,
};

/// Process output
pub const ProcessOutput = struct {
    stdout : []u8,
    stderr : []u8,
    exit_code : u8,
    signal : ?ProcessSignal,
    truncated_stdout : bool,
    truncated_stderr : bool,
};

/// PTY configuration
pub const PTYConfig = struct {
    enabled : bool,
    mode : PTYMode,
    cols : u16,
    rows : u16,
    term : []u8,  // Terminal type (e.g., "xterm-256color")
};

/// Capture options
pub const CaptureOptions = struct {
    include_stdout : bool,
    include_stderr : bool,
    include_exit_code : bool,
    trim_whitespace : bool,
    max_size : u32,
};

// ============================================================================
// Functions
// ============================================================================

/// Create default spawn options
pub fn spawn_options_default() SpawnOptions {
    return SpawnOptions{
        .env = &[_][]u8{},
        .cwd = null,
        .timeout_ms = SPAWN_TIMEOUT_MS,
        .detached = false,
        .pty_enabled = false,
        .pty_cols = PTY_COLS_DEFAULT,
        .pty_rows = PTY_ROWS_DEFAULT,
    };
}

/// Create spawn options with PTY
pub fn spawn_options_with_pty(cols: u16, rows: u16) SpawnOptions {
    return SpawnOptions{
        .env = &[_][]u8{},
        .cwd = null,
        .timeout_ms = SPAWN_TIMEOUT_MS,
        .detached = false,
        .pty_enabled = true,
        .pty_cols = cols,
        .pty_rows = rows,
    };
}

/// Create detached spawn options
pub fn spawn_options_detached() SpawnOptions {
    const base = spawn_options_default();
    return SpawnOptions{
        .env = &[_][]u8{},
        .cwd = null,
        .timeout_ms = 0,  // No timeout for detached
        .detached = true,
        .pty_enabled = base.pty_enabled,
        .pty_cols = base.pty_cols,
        .pty_rows = base.pty_rows,
    };
}

/// Create pipe config
pub fn pipe_config_create() PipeConfig {
    return PipeConfig{
        .stdin = "",
        .stdout_max = MAX_PIPE_BUFFER,
        .stderr_max = MAX_PIPE_BUFFER,
        .merge_output = false,
    };
}

/// Create pipe config with input
pub fn pipe_config_with_input(input: []u8) PipeConfig {
    return PipeConfig{
        .stdin = input,
        .stdout_max = MAX_PIPE_BUFFER,
        .stderr_max = MAX_PIPE_BUFFER,
        .merge_output = false,
    };
}

/// Create PTY config
pub fn pty_config_default() PTYConfig {
    return PTYConfig{
        .enabled = true,
        .mode = .cooked,
        .cols = PTY_COLS_DEFAULT,
        .rows = PTY_ROWS_DEFAULT,
        .term = "xterm-256color",
    };
}

/// Create PTY raw mode config
pub fn pty_config_raw() PTYConfig {
    return PTYConfig{
        .enabled = true,
        .mode = .raw,
        .cols = PTY_COLS_DEFAULT,
        .rows = PTY_ROWS_DEFAULT,
        .term = "xterm-256color",
    };
