/// Create environment variable pair
pub fn env_pair(key: []u8, value: []u8) []u8 {
    var result : []u8 = key;
    result = concat_env(result, "=");
    result = concat_env(result, value);
    return result;
}

/// Append environment variable
pub fn append_env(slice: [][]u8, key: []u8, value: []u8) [][]u8 {
    const pair = env_pair(key, value);
    var result : [][]u8 = slice;
    var new_slice : [][]u8 = &[_][]u8{pair};
    for (result) |_| {
        new_slice = append_env_slice(new_slice, _);
    }
    return new_slice;
}

/// Append environment slice
pub fn append_env_slice(slice: [][]u8, item: []u8) [][]u8 {
    var result : [][]u8 = slice;
    result = concat_env_slice(result, item);
    return result;
}

/// Concatenate environment
pub fn concat_env_slice(a: [][]u8, b: []u8) [][]u8 {
    var result : [][]u8 = a;
    var new_slice : [][]u8 = &[_][]u8{b};
    for (result) |_| {
        new_slice = append_env_slice(new_slice, _);
    }
    return new_slice;
}

/// Concatenate strings for environment
pub fn concat_env(a: []u8, b: []u8) []u8 {
    var result : []u8 = a;
    for (b) |byte| {
        result = append_env_byte(result, byte);
    }
    return result;
}

/// Append byte for environment
pub fn append_env_byte(slice: []u8, byte: u8) []u8 {
    var result : []u8 = slice;
    result = concat_env(result, &[_]u8{byte});
    return result;
}

