// SPDX-License-Identifier: Apache-2.0
// specs/server/provider.t27
// LLM Provider Configuration Specification
// Constitutional Law #4: De-Zig-fication - .t27 is source of truth
// Constitutional Law #5: De-Zig Strict - no new Rust business logic

module Provider {
    use base::types;

    // ====================================================================
    // Provider Types
    // ====================================================================

    enum ProviderType {
        OpenAI = 0,
        Anthropic = 1,
        Google = 2,
        Custom = 3,
    }

    // ====================================================================
    // Provider Configuration
    // ====================================================================

    struct Provider {
        id: str,
        name: str,
        provider_type: ProviderType,
        base_url: str,
        api_key: str,
        enabled: bool,
        default_model: str,
    }

    struct Model {
        id: str,
        provider_id: str,
        name: str,
        context_window: u32,
        max_output_tokens: u32,
        supports_vision: bool,
        supports_streaming: bool,
    }

    // ====================================================================
    // Provider Manager
    // ====================================================================

    struct ProviderManager {
        providers: [16]Provider,
        provider_count: u32,
        default_provider_id: str,
    }

    fn provider_manager_init() -> ProviderManager {
        return ProviderManager{
            providers = [Provider{}; 16],
            provider_count = 0,
            default_provider_id = "",
        };
    }

    // ====================================================================
    // Provider Operations
    // ====================================================================

    fn add_provider(mgr: *ProviderManager, provider: Provider) -> bool {
        if (mgr.provider_count >= 16) {
            return false
        }
        mgr.providers[mgr.provider_count] = provider
        mgr.provider_count = mgr.provider_count + 1
        if (mgr.default_provider_id == "") {
            mgr.default_provider_id = provider.id
        }
        return true
    }

    fn get_provider(mgr: ProviderManager, id: str) -> Provider {
        var i: u32 = 0
        while (i < mgr.provider_count) {
            if (mgr.providers[i].id == id) {
                return mgr.providers[i]
            }
            i = i + 1
        }
        return Provider{id = "", name = "", provider_type = ProviderType::Custom, base_url = "", api_key = "", enabled = false, default_model = ""}
    }

    fn get_default_provider(mgr: ProviderManager) -> Provider {
        return get_provider(mgr, mgr.default_provider_id)
    }

    fn set_default_provider(mgr: *ProviderManager, id: str) -> bool {
        var i: u32 = 0
        while (i < mgr.provider_count) {
            if (mgr.providers[i].id == id) {
                mgr.default_provider_id = id
                return true
            }
            i = i + 1
        }
        return false
    }

    fn list_providers(mgr: ProviderManager) -> [16]Provider {
        return mgr.providers
    }

    fn remove_provider(mgr: *ProviderManager, id: str) -> bool {
        var found: bool = false
        var i: u32 = 0
        while (i < mgr.provider_count) {
            if (mgr.providers[i].id == id) {
                found = true
            }
            if (found and i < mgr.provider_count - 1) {
                mgr.providers[i] = mgr.providers[i + 1]
            }
            i = i + 1
        }
        if (found) {
            mgr.provider_count = mgr.provider_count - 1
            if (mgr.default_provider_id == id) {
                mgr.default_provider_id = ""
            }
        }
        return found
    }

    fn enable_provider(mgr: *ProviderManager, id: str, enabled: bool) -> bool {
        var i: u32 = 0
        while (i < mgr.provider_count) {
            if (mgr.providers[i].id == id) {
                mgr.providers[i].enabled = enabled
                return true
            }
            i = i + 1
        }
        return false
    }

    // ====================================================================
    // Default Providers
    // ====================================================================

    fn create_openai_provider(api_key: str) -> Provider {
        return Provider{
            id = "openai",
            name = "OpenAI",
            provider_type = ProviderType::OpenAI,
            base_url = "https://api.openai.com/v1",
            api_key = api_key,
            enabled = true,
            default_model = "gpt-4o",
        }
    }

    fn create_anthropic_provider(api_key: str) -> Provider {
        return Provider{
            id = "anthropic",
            name = "Anthropic",
            provider_type = ProviderType::Anthropic,
            base_url = "https://api.anthropic.com",
            api_key = api_key,
            enabled = true,
            default_model = "claude-3-5-sonnet-20241022",
        }
    }

    // ====================================================================
    // Tests
    // ====================================================================

    test "provider_type_values" {
        assert(ProviderType::OpenAI == 0)
        assert(ProviderType::Anthropic == 1)
        assert(ProviderType::Google == 2)
        assert(ProviderType::Custom == 3)
    }

    test "add_provider" {
        var mgr = provider_manager_init()
        const provider = create_openai_provider("sk-key")
        const result = add_provider(&mgr, provider)
        assert(result == true)
        assert(mgr.provider_count == 1)
    }

    test "get_provider" {
        var mgr = provider_manager_init()
        const provider = create_openai_provider("sk-key")
        add_provider(&mgr, provider)
        const retrieved = get_provider(mgr, "openai")
        assert(retrieved.id == "openai")
        assert(retrieved.name == "OpenAI")
    }

    test "get_default_provider" {
        var mgr = provider_manager_init()
        const provider = create_openai_provider("sk-key")
        add_provider(&mgr, provider)
        const default = get_default_provider(mgr)
        assert(default.id == "openai")
    }

    test "set_default_provider" {
        var mgr = provider_manager_init()
        const p1 = create_openai_provider("key1")
        const p2 = create_anthropic_provider("key2")
        add_provider(&mgr, p1)
        add_provider(&mgr, p2)
        const result = set_default_provider(&mgr, "anthropic")
        assert(result == true)
        assert(mgr.default_provider_id == "anthropic")
    }

    test "remove_provider" {
        var mgr = provider_manager_init()
        const provider = create_openai_provider("sk-key")
        add_provider(&mgr, provider)
        const result = remove_provider(&mgr, "openai")
        assert(result == true)
        assert(mgr.provider_count == 0)
    }

    test "enable_provider" {
        var mgr = provider_manager_init()
        const provider = create_openai_provider("sk-key")
        add_provider(&mgr, provider)
        const result = enable_provider(&mgr, "openai", false)
        assert(result == true)
        const retrieved = get_provider(mgr, "openai")
        assert(retrieved.enabled == false)
    }

    test "create_openai_provider" {
        const provider = create_openai_provider("my-key")
        assert(provider.id == "openai")
        assert(provider.provider_type == ProviderType::OpenAI)
        assert(provider.default_model == "gpt-4o")
    }

    test "create_anthropic_provider" {
        const provider = create_anthropic_provider("my-key")
        assert(provider.id == "anthropic")
        assert(provider.provider_type == ProviderType::Anthropic)
        assert(provider.default_model == "claude-3-5-sonnet-20241022")
    }

    test "provider_manager_init" {
        const mgr = provider_manager_init()
        assert(mgr.provider_count == 0)
        assert(mgr.default_provider_id == "")
    }
}

