// SPDX-License-Identifier: Apache-2.0
// t27/specs/fpga/dft.t27
// T27 Design-for-Test Specification
// Scan chains, BIST controllers, JTAG TAP, test coverage estimation
// Uses flat arrays + count fields (parser-compatible)
// phi^2 + 1/phi^2 = 3 | TRINITY

module DFT {

    // === Scan chain ===

    pub struct ScanChain {
        name : &str,
        num_regs : u32,
        chain_length_bits : u32,
    }

    fn scan_chain(name: &str, regs: u32) -> ScanChain {
        return ScanChain{
            .name = name,
            .num_regs = regs,
            .chain_length_bits = regs * 32,
        };
    }

    fn scan_chain_cycles(chain: ScanChain) -> u32 {
        return chain.chain_length_bits + 10;
    }

    fn scan_chain_bytes(chain: ScanChain) -> u32 {
        return chain.chain_length_bits / 8;
    }

    // === BIST kind ===

    pub const BistKind = enum(i8) {
        memory_bist = 0,
        logic_bist = 1,
        io_bist = 2,
    }

    // === BIST controller ===

    pub struct BistCtrl {
        name : &str,
        kind : i8,
        patterns : u32,
        pass_threshold : u32,
    }

    fn memory_bist(name: &str, patterns: u32) -> BistCtrl {
        return BistCtrl{
            .name = name,
            .kind = 0,
            .patterns = patterns,
            .pass_threshold = patterns,
        };
    }

    fn logic_bist(name: &str, patterns: u32) -> BistCtrl {
        return BistCtrl{
            .name = name,
            .kind = 1,
            .patterns = patterns,
            .pass_threshold = patterns,
        };
    }

    fn bist_cycles(ctrl: BistCtrl) -> u32 {
        return ctrl.patterns * 2;
    }

    fn bist_coverage(ctrl: BistCtrl, total_faults: u32) -> u32 {
        if total_faults == 0 {
            return 100;
        }
        return ctrl.patterns * 100 / total_faults;
    }

    // === JTAG TAP ===

    pub struct JtagTap {
        name : &str,
        ir_width : u32,
        num_dr_regs : u32,
        bypass_code : u32,
        idcode : u32,
    }

    fn jtag_tap(name: &str, ir_width: u32, idcode: u32) -> JtagTap {
        return JtagTap{
            .name = name,
            .ir_width = ir_width,
            .num_dr_regs = 3,
            .bypass_code = 255,
            .idcode = idcode,
        };
    }

    fn tap_total_bits(tap: JtagTap) -> u32 {
        return tap.ir_width + 32 * tap.num_dr_regs;
    }

    fn tap_state_count() -> u32 {
        return 16;
    }

    // === Test coverage ===

    pub struct TestCoverage {
        scan_coverage : u32,
        bist_coverage : u32,
        atpg_coverage : u32,
        total_coverage : u32,
    }

    fn test_coverage(scan: u32, bist: u32, atpg: u32) -> TestCoverage {
        return TestCoverage{
            .scan_coverage = scan,
            .bist_coverage = bist,
            .atpg_coverage = atpg,
            .total_coverage = (scan + bist + atpg) / 3,
        };
    }

    fn is_acceptable(cov: TestCoverage) -> bool {
        return cov.total_coverage >= 90;
    }

    // === Validation ===

    fn validate_chain(chain: ScanChain) -> u32 {
        var errors : u32 = 0;
        if chain.name == "" {
            errors = errors + 1;
        }
        if chain.num_regs == 0 {
            errors = errors + 1;
        }
        return errors;
    }

    fn validate_bist(ctrl: BistCtrl) -> u32 {
        var errors : u32 = 0;
        if ctrl.name == "" {
            errors = errors + 1;
        }
        if ctrl.patterns == 0 {
            errors = errors + 1;
        }
        return errors;
    }

    fn validate_tap(tap: JtagTap) -> u32 {
        var errors : u32 = 0;
        if tap.name == "" {
            errors = errors + 1;
        }
        if tap.ir_width == 0 {
            errors = errors + 1;
        }
        return errors;
    }

    // === Tests ===

    test scan_chain_creation
        given c = scan_chain("core_chain", 100)
        then c.num_regs == 100
        and c.chain_length_bits == 3200
        and scan_chain_cycles(c) == 3210
        and scan_chain_bytes(c) == 400

    test memory_bist_creation
        given b = memory_bist("bram_bist", 8)
        then b.kind == 0
        and b.patterns == 8
        and bist_cycles(b) == 16

    test logic_bist_creation
        given b = logic_bist("logic_bist", 16)
        then b.kind == 1
        and b.patterns == 16

    test bist_coverage_full
        given b = memory_bist("bist", 100)
        then bist_coverage(b, 100) == 100

    test bist_coverage_partial
        given b = memory_bist("bist", 50)
        then bist_coverage(b, 200) == 25

    test bist_coverage_zero_faults
        given b = memory_bist("bist", 10)
        then bist_coverage(b, 0) == 100

    test jtag_tap_creation
        given t = jtag_tap("main_tap", 8, 305419896)
        then t.ir_width == 8
        and t.num_dr_regs == 3
        and t.bypass_code == 255
        and tap_total_bits(t) == 104

    test tap_state_count
        then tap_state_count() == 16

    test test_coverage_creation
        given c = test_coverage(95, 90, 85)
        then c.scan_coverage == 95
        and c.bist_coverage == 90
        and c.atpg_coverage == 85
        and c.total_coverage == 90

    test test_coverage_acceptable
        given c = test_coverage(95, 95, 90)
        then is_acceptable(c) == true

    test test_coverage_not_acceptable
        given c = test_coverage(80, 80, 80)
        then is_acceptable(c) == false

    test validate_chain_ok
        given c = scan_chain("ok", 10)
        then validate_chain(c) == 0

    test validate_chain_empty
        given c = ScanChain{.name = "", .num_regs = 0, .chain_length_bits = 0}
        then validate_chain(c) > 0

    test validate_bist_ok
        given b = memory_bist("ok", 8)
        then validate_bist(b) == 0

    test validate_bist_empty
        given b = BistCtrl{.name = "", .kind = 0, .patterns = 0, .pass_threshold = 0}
        then validate_bist(b) > 0

    test validate_tap_ok
        given t = jtag_tap("ok", 4, 0)
        then validate_tap(t) == 0

    test validate_tap_empty
        given t = JtagTap{.name = "", .ir_width = 0, .num_dr_regs = 0, .bypass_code = 0, .idcode = 0}
        then validate_tap(t) > 0

    // === Invariants ===

    invariant scan_cycles_positive
        given c = scan_chain("inv", 10)
        assert scan_chain_cycles(c) > 0

    invariant coverage_bounded
        given c = test_coverage(100, 100, 100)
        assert c.total_coverage <= 100

    // === Benchmarks ===

    bench dft_latency
        measure: nanoseconds for scan_chain("bench", 1000)
        target: < 50ns
}

// phi^2 + 1/phi^2 = 3 | TRINITY

// SPDX-License-Identifier: Apache-2.0
// t27/specs/fpga/cts.t27
// T27 Clock Tree Synthesis Specification
// PLL configuration, clock buffer trees, skew estimation
// Artix-7: BUFH=0.05ns, BUFG=0.1ns, PLL jitter=50ps, max skew=100ps
// Uses flat arrays + count fields (parser-compatible)
// phi^2 + 1/phi^2 = 3 | TRINITY

module CTS {

    pub struct PllConfig {
        name : &str,
        input_mhz : u32,
        output_mhz : u32,
        multiply : u32,
        divide : u32,
        jitter_ps : u32,
    }

    fn pll_config(name: &str, input_mhz: u32, output_mhz: u32) -> PllConfig {
        var m : u32 = 1;
        var d : u32 = 1;
        if input_mhz > 0 {
            d = input_mhz;
            m = output_mhz;
        }
        return PllConfig{
            .name = name,
            .input_mhz = input_mhz,
            .output_mhz = output_mhz,
            .multiply = m,
            .divide = d,
            .jitter_ps = 50,
        };
    }

    fn pll_period_ps(pll: PllConfig) -> u32 {
        if pll.output_mhz == 0 {
            return 0;
        }
        return 1000000000 / pll.output_mhz;
    }

    pub struct ClockBuffer {
        name : &str,
        delay_ps : u32,
        fanout : u32,
    }

    fn bufg(name: &str) -> ClockBuffer {
        return ClockBuffer{ .name = name, .delay_ps = 100, .fanout = 32 };
    }

    fn bufh(name: &str) -> ClockBuffer {
        return ClockBuffer{ .name = name, .delay_ps = 50, .fanout = 16 };
    }

    fn bufg_has_higher_fanout(b: ClockBuffer) -> bool {
        return b.fanout >= 32;
    }

    pub struct ClockTree {
        root : &str,
        num_levels : u32,
        total_buffers : u32,
        max_skew_ps : u32,
    }

    fn clock_tree(root: &str, levels: u32, bufs: u32) -> ClockTree {
        return ClockTree{
            .root = root,
            .num_levels = levels,
            .total_buffers = bufs,
            .max_skew_ps = 100,
        };
    }

    fn tree_delay_ps(tree: ClockTree, buf_delay: u32) -> u32 {
        return tree.num_levels * buf_delay;
    }

    fn skew_ok(tree: ClockTree, max_allowed_ps: u32) -> bool {
        return tree.max_skew_ps <= max_allowed_ps;
    }

    pub struct CtsReport {
        num_clocks : u32,
        num_plls : u32,
        total_buffers : u32,
        worst_skew_ps : u32,
        worst_latency_ps : u32,
        has_violations : bool,
    }

    fn cts_ok(clocks: u32, plls: u32, bufs: u32, skew: u32, latency: u32) -> CtsReport {
        return CtsReport{
            .num_clocks = clocks,
            .num_plls = plls,
            .total_buffers = bufs,
            .worst_skew_ps = skew,
            .worst_latency_ps = latency,
            .has_violations = false,
        };
    }

    fn passed(r: CtsReport) -> bool {
        return r.has_violations == false;
    }

    // === Auto tree estimation ===

    fn est_buffers_needed(num_sinks: u32) -> u32 {
        if num_sinks <= 16 {
            return 1;
        }
        return num_sinks / 16 + 1;
    }

    fn est_tree_levels(num_sinks: u32) -> u32 {
        if num_sinks <= 16 {
            return 1;
        }
        if num_sinks <= 256 {
            return 2;
        }
        return 3;
    }

    // === Validation ===

    fn validate_pll(pll: PllConfig) -> u32 {
        var errors : u32 = 0;
        if pll.name == "" { errors = errors + 1; }
        if pll.output_mhz == 0 { errors = errors + 1; }
        return errors;
    }

    // === Tests ===

    test pll_config_creation
        given p = pll_config("sys_pll", 100, 200)
        then p.input_mhz == 100
        and p.output_mhz == 200
        and pll_period_ps(p) == 5000000

    test bufg_creation
        given b = bufg("clk_buf")
        then b.delay_ps == 100
        and b.fanout == 32
        and bufg_has_higher_fanout(b) == true

    test bufh_creation
        given b = bufh("clk_h")
        then b.delay_ps == 50
        and b.fanout == 16
        and bufg_has_higher_fanout(b) == false

    test clock_tree_creation
        given t = clock_tree("clk", 2, 5)
        then t.root == "clk"
        and t.num_levels == 2
        and t.total_buffers == 5
        and t.max_skew_ps == 100

    test tree_delay
        given t = clock_tree("clk", 3, 8)
        then tree_delay_ps(t, 100) == 300

    test skew_ok_yes
        given t = clock_tree("clk", 2, 5)
        then skew_ok(t, 200) == true

    test skew_ok_no
        given t = clock_tree("clk", 2, 5)
        then skew_ok(t, 50) == false

    test cts_report_ok
        given r = cts_ok(2, 1, 10, 80, 300)
        then passed(r) == true
        and r.has_violations == false

    test est_buffers_one
        then est_buffers_needed(10) == 1

    test est_buffers_many
        then est_buffers_needed(100) == 7

    test est_tree_levels_one
        then est_tree_levels(10) == 1

    test est_tree_levels_two
        then est_tree_levels(100) == 2

    test est_tree_levels_three
        then est_tree_levels(500) == 3

    test validate_pll_ok
        given p = pll_config("ok", 100, 200)
        then validate_pll(p) == 0

    test validate_pll_empty
        given p = PllConfig{.name = "", .input_mhz = 100, .output_mhz = 0, .multiply = 1, .divide = 1, .jitter_ps = 50}
        then validate_pll(p) > 0

    // === Invariants ===

    invariant bufg_delay_positive
        given b = bufg("inv")
        assert b.delay_ps > 0

    invariant skew_non_negative
        given t = clock_tree("inv", 2, 5)
