    return InitializationOptions{
        .process_id = 0,
        .root_path = root_path,
        .root_uri = "",
        .initialization_options = "",
        .capabilities = client_capabilities_default(),
        .trace = .off,
        .workspace_folders = &[_]WorkspaceFolder{},
    };
}

/// Create text document sync options
pub fn text_document_sync_options_create(open_close: bool, sync_kind: TextDocumentSyncKind) TextDocumentSyncOptions {
    return TextDocumentSyncOptions{
        .open_close = open_close,
        .change = sync_kind,
        .will_save = false,
        .will_save_wait_until = false,
        .save = SaveOptions{ .include_text = false },
    };
}

/// Create work done progress begin
pub fn work_done_progress_begin_create(title: []u8) WorkDoneProgressBegin {
    return WorkDoneProgressBegin{
        .title = title,
        .cancellable = false,
        .message = "",
        .percentage = 0,
    };
}

