    return LogTraceParams{
        .message = message,
        .verbose = "",
    };
}

/// Check if trace is enabled
pub fn trace_is_enabled(trace: TraceValue) bool {
    return trace != .off;
}

/// Get trace level string
pub fn trace_to_string(trace: TraceValue) []u8 {
    return switch (trace) {
        .off => "off",
        .messages => "messages",
        .verbose => "verbose",
    };
