        // `- name` bullets, leaving `kind : Enum, variants : ,` with no names.
        enum : [core, dev, forge, agent, mcp, system],
    };

    // A TAGGED UNION, and its payloads were not lost either. Recovered from
    // trinity-fpga specs/tri/tri_namespace.tri:17-25, where `variants:` carries
