// Network metrics - ultra-minimal, all-inline, no-let

module NetworkMetrics {
    use base::types;

    fn get_sent(metrics: u32) -> u32 {
        return metrics;
    }

    fn inc_sent(metrics: u32) -> u32 {
        return (metrics + 1);
    }

    fn get_recv(metrics: u32) -> u32 {
        return metrics;
    }

    fn inc_recv(metrics: u32) -> u32 {
        return (metrics + 1);
    }

    fn get_success(metrics: u32) -> u32 {
        return metrics;
    }

    fn inc_success(metrics: u32) -> u32 {
        return (metrics + 1);
    }

    fn success_rate(sent: u32, success: u32) -> u8 {
        if (sent == 0) {
            return 100;
        }

        if (sent >= success) {
            return (((success as u16) * 100) / (sent as u16)) as u8;
        } else {
            return 0;
        }
    }

    // ---- Tests ----

    test initial_zero {
        assert(get_sent(0) == 0, "initial");
    }

    test inc_sent_works {
        m1 = inc_sent(0);
        assert(get_sent(m1) == 1, "inc works");
    }

    test inc_recv_works {
        m1 = inc_recv(0);
        assert(get_recv(m1) == 1, "inc works");
    }

    test inc_success_works {
        m1 = inc_success(0);
        assert(get_success(m1) == 1, "inc success");
    }

    test success_rate_perfect {
        assert(success_rate(1, 1) == 100, "100%");
    }

    test success_rate_zero_sent {
        assert(success_rate(0, 0) == 100, "none sent = 100%");
    }

    test success_rate_half {
        assert(success_rate(10, 5) == 50, "50%");
    }

    test success_rate_zero_success {
        assert(success_rate(10, 0) == 0, "0%");
    }
}

// TRI-NET block interleaver: spread consecutive datagrams across FEC codewords so a
// BURST of channel errors (fading drops a run of adjacent datagrams) becomes at most
// one error per codeword -- which the single-erasure XOR-FEC (tri_fec) can then
// recover. Without interleaving a burst wipes >=2 datagrams of one codeword and FEC
// fails; with depth-D interleaving any burst of length <= D is survivable.
//
// Layout: a block of D*W datagrams. Codewords are the W-wide ROWS (one FEC group per
// row). Write row-major (original order), transmit COLUMN-major, so consecutive
// transmitted datagrams come from different rows/codewords.

module TriInterleave {
    use base::types;

    const DEPTH_CAP: u32 = 64; // max interleaver depth (bounds latency + memory)

    // Original (codeword-major) index -> transmit position. Element o sits at
    // (row = o/W, col = o%W); read column-major => t = col*D + row.
    fn ilv_tx_pos(o: u32, depth: u32, width: u32) -> u32 {
        return ((o % width) * depth) + (o / width);
    }

    // Transmit position -> original index (inverse). t maps to (col = t/D, row = t%D);
    // original o = row*W + col.
    fn ilv_orig(t: u32, depth: u32, width: u32) -> u32 {
        return ((t % depth) * width) + (t / depth);
    }

    // Which codeword (FEC group) an original index belongs to.
    fn ilv_codeword(o: u32, width: u32) -> u32 {
        return o / width;
    }

    // Adaptive depth: pick an interleaver depth that survives a measured burst of
    // `max_burst` datagrams -- depth must be >= max_burst (so a burst spreads to <=1
    // error per codeword), clamped to DEPTH_CAP (bounded latency/memory). A depth
    // below the burst would leave >=2 errors in some codeword and FEC would fail.
    fn choose_depth(max_burst: u32) -> u32 {
        if (max_burst == 0) {
            return 1;
        } else if (max_burst >= DEPTH_CAP) {
            return DEPTH_CAP;
        } else {
            return max_burst;
        }
    }

    // Does depth D survive a burst of length B? (survivable iff D >= B, up to the cap.)
    fn depth_survives(depth: u32, burst: u32) -> bool {
        return depth >= burst;
    }

    // ---- Tests / invariants ----

    // Round-trip: interleave then de-interleave is identity.
    test ilv_roundtrip {
        assert(ilv_orig(ilv_tx_pos(0, 8, 4), 8, 4) == 0, "o=0");
        assert(ilv_orig(ilv_tx_pos(7, 8, 4), 8, 4) == 7, "o=7");
        assert(ilv_orig(ilv_tx_pos(31, 8, 4), 8, 4) == 31, "o=31");
        assert(ilv_orig(ilv_tx_pos(13, 8, 4), 8, 4) == 13, "o=13");
    }

    // Consecutive transmit positions map to DIFFERENT codewords (the whole point):
    // a 2-adjacent burst can't hit the same FEC group.
    test ilv_adjacent_differ {
        c0 = ilv_codeword(ilv_orig(0, 8, 4), 4);
        c1 = ilv_codeword(ilv_orig(1, 8, 4), 4);
        c2 = ilv_codeword(ilv_orig(2, 8, 4), 4);
        assert(c0 != c1, "tx0 vs tx1 different codeword");
        assert(c1 != c2, "tx1 vs tx2 different codeword");
        assert(c0 == 0, "tx0 -> codeword 0");
        assert(c1 == 1, "tx1 -> codeword 1");
    }

    // A burst of length D=8 (one full column) touches 8 DISTINCT codewords, i.e. one
    // datagram from each of the 8 rows -> at most one error per codeword.
    test ilv_burst_spreads {
        // transmit positions 0..7 are the first column: they must be codewords 0..7
        assert(ilv_codeword(ilv_orig(0, 8, 4), 4) == 0, "t0->cw0");
        assert(ilv_codeword(ilv_orig(3, 8, 4), 4) == 3, "t3->cw3");
        assert(ilv_codeword(ilv_orig(7, 8, 4), 4) == 7, "t7->cw7");
        // position 8 wraps to the next column, back to codeword 0
        assert(ilv_codeword(ilv_orig(8, 8, 4), 4) == 0, "t8->cw0 (next column)");
    }

    // Permutation sanity: transmit positions of two different originals never collide.
    test ilv_is_permutation {
        assert(ilv_tx_pos(0, 8, 4) != ilv_tx_pos(1, 8, 4), "distinct 0,1");
        assert(ilv_tx_pos(4, 8, 4) != ilv_tx_pos(5, 8, 4), "distinct 4,5");
        assert(ilv_tx_pos(0, 8, 4) == 0, "o0 -> t0");
        assert(ilv_tx_pos(4, 8, 4) == 1, "o4(row1,col0) -> t1");
    }

    // Adaptive depth matches the measured burst, and the chosen depth survives it.
    test choose_depth_matches_burst {
        assert(choose_depth(5) == 5, "burst 5 -> depth 5");
        assert(choose_depth(12) == 12, "burst 12 -> depth 12");
        assert(depth_survives(choose_depth(12), 12), "chosen depth survives its burst");
    }

    // A fixed depth below the burst fails; the adaptive choice fixes it.
    test choose_depth_beats_fixed {
        assert(depth_survives(8, 12) == false, "fixed depth 8 fails a burst of 12");
        assert(depth_survives(choose_depth(12), 12) == true, "adaptive depth survives 12");
    }

    // Clamped to the cap; a zero burst still yields a valid depth of 1.
    test choose_depth_bounds {
        assert(choose_depth(0) == 1, "no burst -> depth 1");
        assert(choose_depth(1000) == DEPTH_CAP, "huge burst clamps to cap");
    }
}

// Access Control - node authentication and authorization
// Simplified RBAC for mesh network security

module AccessControl {
    use base::types;

    const MAX_NODES: u32 = 8;
    const ROLE_NONE: u32 = 0;
    const ROLE_GUEST: u32 = 1;
    const ROLE_USER: u32 = 2;
    const ROLE_ADMIN: u32 = 3;
    const PERMIT: u32 = 1;
    const DENY: u32 = 0;

    // Node credentials [node_id][role][auth_token][authorized]
    fn create_node_creds(node_id: u32, role: u32, auth_token: u32, authorized: u32) -> u32 {
        return (((node_id & 0xFF) << 24) |
                ((role & 0x3) << 22) |
                ((auth_token & 0x3FF) << 12) |
                ((authorized & 0x1) << 11));
    }

    fn get_node_id(creds: u32) -> u32 {
        return ((creds >> 24) & 0xFF);
    }

    fn get_role(creds: u32) -> u32 {
        return ((creds >> 22) & 0x3);
    }

    fn get_auth_token(creds: u32) -> u32 {
        return ((creds >> 12) & 0x3FF);
    }

    fn is_authorized(creds: u32) -> u32 {
        return ((creds >> 11) & 0x1);
    }

    // Access policy [resource][min_role][guest][user][admin]
    fn create_policy(resource: u32, min_role: u32, guest_perm: u32, user_perm: u32, admin_perm: u32) -> u32 {
        return (((resource & 0xF) << 28) |
                ((min_role & 0x3) << 26) |
                ((guest_perm & 0x1) << 25) |
                ((user_perm & 0x1) << 24) |
                ((admin_perm & 0x1) << 23));
    }

    fn get_resource(policy: u32) -> u32 {
        return ((policy >> 28) & 0xF);
    }

    fn get_min_role(policy: u32) -> u32 {
        return ((policy >> 26) & 0x3);
    }

    fn get_guest_perm(policy: u32) -> u32 {
        return ((policy >> 25) & 0x1);
    }

    fn get_user_perm(policy: u32) -> u32 {
        return ((policy >> 24) & 0x1);
    }

    fn get_admin_perm(policy: u32) -> u32 {
        return ((policy >> 23) & 0x1);
    }

    // Check if role meets minimum requirement
    fn role_meets_minimum(role: u32, min_role: u32) -> bool {
        return (role >= min_role);
    }

    // Check access permission
    fn check_access(policy: u32, role: u32) -> u32 {
        let min_role = get_min_role(policy);

        if (!role_meets_minimum(role, min_role)) {
            return DENY; // Role too low
        }

        if (role == ROLE_GUEST) {
            return get_guest_perm(policy);
        } else if (role == ROLE_USER) {
            return get_user_perm(policy);
        } else if (role == ROLE_ADMIN) {
            return get_admin_perm(policy);
        }

        return DENY; // Invalid role
    }

    // Verify node credentials
    fn verify_creds(creds: u32, provided_token: u32) -> bool {
        if (is_authorized(creds) == 0) {
            return false; // Node not authorized
        }

        return (get_auth_token(creds) == provided_token);
    }

    // Authorize node
    fn authorize_node(creds: u32) -> u32 {
        let node_id = get_node_id(creds);
        let role = get_role(creds);
        let token = get_auth_token(creds);
        return create_node_creds(node_id, role, token, PERMIT);
    }

    // Revoke node authorization
    fn revoke_node(creds: u32) -> u32 {
        let node_id = get_node_id(creds);
        let role = get_role(creds);
        let token = get_auth_token(creds);
        return create_node_creds(node_id, role, token, DENY);
    }

    // Change node role
    fn change_role(creds: u32, new_role: u32) -> u32 {
        let node_id = get_node_id(creds);
        let token = get_auth_token(creds);
        let auth = is_authorized(creds);
        return create_node_creds(node_id, new_role, token, auth);
    }

    // Check resource access for node
    fn check_resource_access(creds: u32, policy: u32, provided_token: u32) -> u32 {
        if (!verify_creds(creds, provided_token)) {
            return DENY; // Invalid credentials
        }

        let role = get_role(creds);
        return check_access(policy, role);
    }

    // ---- Tests ----

    test create_node_creds_basic {
        creds = create_node_creds(5, ROLE_USER, 0x123, 1);
        assert(get_node_id(creds) == 5, "node id");
        assert(get_role(creds) == ROLE_USER, "user role");
        assert(get_auth_token(creds) == 0x123, "auth token");
        assert(is_authorized(creds) == 1, "authorized");
    }

    test create_policy_basic {
        policy = create_policy(1, ROLE_USER, 0, 1, 1);
        assert(get_resource(policy) == 1, "resource");
        assert(get_min_role(policy) == ROLE_USER, "min role");
        assert(get_guest_perm(policy) == 0, "guest denied");
        assert(get_user_perm(policy) == 1, "user permitted");
    }

    test role_meets_minimum_true {
        assert(role_meets_minimum(ROLE_USER, ROLE_GUEST) == true, "user >= guest");
        assert(role_meets_minimum(ROLE_ADMIN, ROLE_USER) == true, "admin >= user");
    }

    test role_meets_minimum_false {
        assert(role_meets_minimum(ROLE_GUEST, ROLE_USER) == false, "guest < user");
        assert(role_meets_minimum(ROLE_USER, ROLE_ADMIN) == false, "user < admin");
    }

    test check_access_admin {
        policy = create_policy(1, ROLE_GUEST, 0, 0, 1);
        assert(check_access(policy, ROLE_ADMIN) == 1, "admin permitted");
    }

    test check_access_user {
        policy = create_policy(1, ROLE_USER, 0, 1, 1);
        assert(check_access(policy, ROLE_USER) == 1, "user permitted");
    }

    test check_access_guest_denied {
        policy = create_policy(1, ROLE_USER, 0, 1, 1);
        assert(check_access(policy, ROLE_GUEST) == 0, "guest denied (min role)");
    }

    test verify_creds_valid {
        creds = create_node_creds(5, ROLE_USER, 0x123, 1);
        assert(verify_creds(creds, 0x123) == true, "valid credentials");
    }

    test verify_creds_invalid_token {
        creds = create_node_creds(5, ROLE_USER, 0x123, 1);
        assert(verify_creds(creds, 0x999) == false, "invalid token");
    }

    test verify_creds_unauthorized {
        creds = create_node_creds(5, ROLE_USER, 0x123, 0);
        assert(verify_creds(creds, 0x123) == false, "unauthorized node");
    }

    test authorize_node_works {
        creds = create_node_creds(5, ROLE_USER, 0x123, 0);
        new_creds = authorize_node(creds);
        assert(is_authorized(new_creds) == 1, "node authorized");
    }

    test revoke_node_works {
        creds = create_node_creds(5, ROLE_USER, 0x123, 1);
        new_creds = revoke_node(creds);
        assert(is_authorized(new_creds) == 0, "node revoked");
    }

    test change_role_works {
        creds = create_node_creds(5, ROLE_USER, 0x123, 1);
        new_creds = change_role(creds, ROLE_ADMIN);
        assert(get_role(new_creds) == ROLE_ADMIN, "role changed");
        assert(is_authorized(new_creds) == 1, "authorization kept");
    }

    test check_resource_access_full_grant {
        creds = create_node_creds(5, ROLE_USER, 0x123, 1);
        policy = create_policy(1, ROLE_GUEST, 0, 1, 1);
        assert(check_resource_access(creds, policy, 0x123) == 1, "access granted");
    }

    test check_resource_access_invalid_creds {
        creds = create_node_creds(5, ROLE_USER, 0x123, 1);
        policy = create_policy(1, ROLE_GUEST, 0, 1, 1);
        assert(check_resource_access(creds, policy, 0x999) == 0, "access denied");
    }

    test check_resource_access_role_too_low {
        creds = create_node_creds(5, ROLE_GUEST, 0x123, 1);
        policy = create_policy(1, ROLE_USER, 0, 1, 1);
        assert(check_resource_access(creds, policy, 0x123) == 0, "role too low");
    }
}

// Link quality monitoring with EWMA-based prediction
// Research: EWMA provides optimal balance between responsiveness and stability

module LinkQualityMonitor {
    // EWMA configuration constants
    const ALPHA_Q8: u8 = 0x20;  // 0.125 in Q8 (1/8) - research-backed optimal
    const ONE_MINUS_ALPHA_Q8: u8 = 0xE0;  // 0.875 in Q8

    // History configuration
    const MAX_HISTORY: u8 = 8;
    const MIN_HISTORY: u8 = 4;

    // Thresholds for quality assessment
    const QUALITY_GOOD: u8 = 0x30;    // 3.0 in Q8
    const QUALITY_POOR: u8 = 0x60;    // 6.0 in Q8
    const TREND_THRESHOLD: u8 = 0x05;  // Small positive trend

    // Calculate EWMA (Exponentially Weighted Moving Average)
    // Formula: est = α·sample + (1-α)·est
    fn update_ewma(current: u8, sample: u8) -> u8 {
        // Fixed-point Q8 calculation
        // term1 = α * sample
        let term1: u16 = ((ALPHA_Q8 as u16) * (sample as u16)) >> 8;

        // term2 = (1-α) * current  
        let term2: u16 = ((ONE_MINUS_ALPHA_Q8 as u16) * (current as u16)) >> 8;

        let new_estimate: u16 = term1 + term2;

        // Cap at the u8 ceiling: the old body capped at 0x280, which cannot
        // fit the u8 return (and the whole Rust-style body was silently
        // DROPPED by the parser -- the fn was an unimplemented stub).
        if (new_estimate > 0xFF) {
            return 0xFF;
        }
        return new_estimate as u8;
    }

    // Calculate trend based on historical data
    fn calculate_trend(history: [u8; 8]) -> i8 {
        // Compare recent average vs older average
        let recent_avg: u8 = ((history[7] as u16 + history[6] as u16 + 
                               history[5] as u16 + history[4] as u16) >> 2) as u8;

        let older_avg: u8 = ((history[3] as u16 + history[2] as u16 + 
                              history[1] as u16 + history[0] as u16) >> 2) as u8;

        // Trend = recent - older (positive = worsening)
        if (recent_avg > older_avg) {
            return (recent_avg - older_avg) as i8;
        }
        return -((older_avg - recent_avg) as i8);
    }

    // Predict next ETX value based on trend
    fn predict_next_etx(current: u8, trend: i8) -> u8 {
        let prediction: i16 = (current as i16) + (trend as i16);

        // Ensure reasonable bounds (1.0 to 10.0 in Q8 = 0x40 to 0x280)
        // Caps must fit the u8 return: the old 0x280 ceiling did not.
        if (prediction < 0x40) {
            return 0x40; // Minimum ETX of 1.0
        }
        if (prediction > 0xFF) {
            return 0xFF;
        }
        return prediction as u8;
    }

    // Determine if link quality is degrading
    fn is_degrading(current_etx: u8, trend: i8) -> bool {
        // Degradation criteria: ETX is poor AND trend is positive (worsening)
        return (current_etx > QUALITY_POOR) && (trend > TREND_THRESHOLD);
    }

    // Calculate quality score (0-255, lower is better)
    fn quality_score(etx: u8, latency_ms: u16) -> u8 {
        // Combined metric: 70% ETX + 30% latency (normalized)
        let etx_component: u16 = ((etx as u16) * 7) / 10;  // 70% weight
        let latency_component: u16 = latency_ms / 100;     // 30% weight

        let combined: u16 = etx_component + latency_component;

        // Cap at 255
        if (combined > 255) {
            return 255;
        }
        return combined as u8;
    }

    // Convert quality score to classification
    fn classify_quality(score: u8) -> u8 {
        if (score <= 50) {
            return 0; // Excellent
        }
        if (score <= 100) {
            return 1; // Good
        }
        if (score <= 150) {
            return 2; // Fair
        }
        if (score <= 200) {
            return 3; // Poor
        }
        return 4; // Very Poor
    }

    // ---- Tests (transcribed from the former testbench block: testbench
    // blocks are not emitted into any executable backend, so these
    // assertions had never actually run) ----

    test ewma_calculation {
        // Update from 2.0 to 3.0
        let current: u8 = 0x40;  // 2.0 in Q8
        let sample: u8 = 0x60;  // 3.0 in Q8

        let new_etx: u8 = update_ewma(current, sample);

        // Should be between current and sample (weighted average)
        assert(new_etx > current, "new_etx > current");
        assert(new_etx < sample, "new_etx < sample");
    }

    test trend_detection {
        // Improving quality (decreasing ETX)
        let improving_history: [u8; 8] = [0x70, 0x68, 0x60, 0x58, 0x50, 0x48, 0x40, 0x38];
        let trend: i8 = calculate_trend(improving_history);
        assert(trend < 0, "trend < 0");  // Negative trend = improving

        // Worsening quality (increasing ETX)
        let worsening_history: [u8; 8] = [0x40, 0x48, 0x50, 0x58, 0x60, 0x68, 0x70, 0x78];
        let trend2: i8 = calculate_trend(worsening_history);
        assert(trend2 > 0, "trend2 > 0");  // Positive trend = worsening
    }

    test etx_prediction {
        // Current ETX of 3.0, positive trend of 0.5
        let current: u8 = 0x60;  // 3.0 in Q8
        let trend: i8 = 0x08;   // +0.5 trend

        let predicted: u8 = predict_next_etx(current, trend);

        // Should predict slightly higher ETX
        assert(predicted > current, "predicted > current");
        assert(predicted < 0x70, "predicted < 0x70");  // Reasonable upper bound
    }

    test degradation_detection {
        // Poor ETX with worsening trend
        assert(is_degrading(0x70, 0x10) == true, "is_degrading 0x70 0x10 == true");

        // Poor ETX with improving trend
        assert(is_degrading(0x70, -0x10) == false, "is_degrading 0x70 -0x10 == false");

        // Good ETX regardless of trend
        assert(is_degrading(0x30, 0x10) == false, "is_degrading 0x30 0x10 == false");
    }

    test quality_score_calculation {
        let etx: u8 = 0x50;    // 4.0 in Q8
        let latency: u16 = 100; // 100ms

        let score: u8 = quality_score(etx, latency);

        // Score should be reasonable
        assert(score > 50, "score > 50");
        assert(score < 200, "score < 200");
    }

    test quality_classification {
        assert(classify_quality(30) == 0, "classify_quality 30 == 0");  // Excellent
        assert(classify_quality(80) == 1, "classify_quality 80 == 1");  // Good
        assert(classify_quality(125) == 2, "classify_quality 125 == 2"); // Fair
        assert(classify_quality(175) == 3, "classify_quality 175 == 3"); // Poor
        assert(classify_quality(225) == 4, "classify_quality 225 == 4"); // Very Poor
    }
}

// Nickname directory policy.
// String normalization and network storage are adapter responsibilities.
// phi^2 + phi^-2 = 3

module NicknameDirectory {
    use base::types;

    const RESULT_OFFLINE_INTERNET: u8 = 0;
    const RESULT_CACHED_MESH: u8 = 1;
    const RESULT_ONLINE_INTERNET: u8 = 2;
    const RESULT_LIVE_MESH: u8 = 3;

    const NICKNAME_MIN_LENGTH: u8 = 3;
    const NICKNAME_MAX_LENGTH: u8 = 20;
    const MAX_EDIT_DISTANCE: u8 = 1;
    const MIN_CONFUSING_PREFIX: u8 = 4;
    const MESH_ROUTE_CACHE_TTL_SECONDS: u32 = 604800;

    const CLAIM_REJECTED: u8 = 0;
    const CLAIM_MESH_LOCAL: u8 = 1;
    const CLAIM_VERIFIED: u8 = 2;

    // Adapters restrict normalized nicknames to lowercase ASCII letters,
    // decimal digits, and underscore. The first character must be a letter.
    fn nickname_shape_is_valid(length: u8, starts_with_letter: bool, invalid_characters: u8) -> bool {
        if (length < NICKNAME_MIN_LENGTH || length > NICKNAME_MAX_LENGTH) {
            return false;
        }
        return starts_with_letter && invalid_characters == 0;
    }

    // Exact normalized collisions and near-copy names are rejected. Prefix
    // checks only apply when at least four characters are shared.
    fn nickname_is_confusing(exact_match: bool, edit_distance: u8, shared_prefix: u8) -> bool {
        if (exact_match) {
            return true;
        }
        if (edit_distance <= MAX_EDIT_DISTANCE) {
            return true;
        }
        return shared_prefix >= MIN_CONFUSING_PREFIX && edit_distance == 2;
    }

    // Global verification requires the authoritative registry. A connected
    // mesh can issue only a provisional claim.
    fn claim_status(shape_valid: bool, confusing: bool, registry_reachable: bool, registry_accepts: bool) -> u8 {
        if (!shape_valid || confusing) {
            return CLAIM_REJECTED;
        }
        if (registry_reachable && registry_accepts) {
            return CLAIM_VERIFIED;
        }
        if (!registry_reachable) {
            return CLAIM_MESH_LOCAL;
        }
        return CLAIM_REJECTED;
    }

    fn may_route_by_nickname(claim: u8, signature_valid: bool) -> bool {
        return (claim == CLAIM_MESH_LOCAL || claim == CLAIM_VERIFIED) && signature_valid;
    }

    // A global nickname belongs to the account, not to one installation. Two
    // separately keyed devices in the same account may advertise the same nick.
    fn nickname_owner_matches(claim_account_id: u64, device_account_id: u64) -> bool {
        return claim_account_id != 0 && claim_account_id == device_account_id;
    }

    // Public Internet discovery is an exact-address operation, not a people
    // catalog. A normalized query may reveal at most the one matching account.
    fn exact_lookup_may_return(query_shape_valid: bool, exact_match: bool, active_devices: u16) -> bool {
        return query_shape_valid && exact_match && active_devices > 0;
    }

    // A previously verified private mesh address remains available for an
    // explicit manual retry. Cache freshness does not prove live reachability,
    // so Auto must require a current signed Bonjour advertisement.
    fn cached_mesh_route_is_fresh(last_seen: u32, now: u32) -> bool {
        if (now < last_seen) {
            return false;
        }
        return (now - last_seen) <= MESH_ROUTE_CACHE_TTL_SECONDS;
    }

    fn auto_route_may_use_mesh(live_advertisement: bool, cached_route_fresh: bool) -> bool {
        if (cached_route_fresh) {
            return live_advertisement;
        }
        return live_advertisement;
    }

    // A 169.254/16 route is scoped to one temporary interface session and must
    // never survive Bonjour removal or an app restart.
    fn mesh_route_may_be_cached(is_link_local: bool) -> bool {
        return !is_link_local;
    }

    // Search keeps both discovery sources and selects one row per device.
    // A live local advertisement is the strongest presence proof.
    fn directory_result_rank(is_mesh: bool, online: bool) -> u8 {
        if (is_mesh && online) {
            return RESULT_LIVE_MESH;
        }
        if (!is_mesh && online) {
            return RESULT_ONLINE_INTERNET;
        }
        if (is_mesh) {
            return RESULT_CACHED_MESH;
        }
        return RESULT_OFFLINE_INTERNET;
    }

    // The current signed UDP adapter accepts numeric IPv4 only. Bonjour
    // discovery resolves hostnames before they reach this policy.
    fn direct_mesh_target_is_supported(is_numeric_ipv4: bool) -> bool {
        return is_numeric_ipv4;
    }

    test nickname_shape_rules {
        assert(nickname_shape_is_valid(3, true, 0) == true, "minimum valid");
        assert(nickname_shape_is_valid(2, true, 0) == false, "too short");
        assert(nickname_shape_is_valid(21, true, 0) == false, "too long");
        assert(nickname_shape_is_valid(8, false, 0) == false, "must start with letter");
        assert(nickname_shape_is_valid(8, true, 1) == false, "invalid character");
    }

    test exact_and_near_copy_are_confusing {
        assert(nickname_is_confusing(true, 0, 8) == true, "exact collision");
        assert(nickname_is_confusing(false, 1, 0) == true, "near copy");
        assert(nickname_is_confusing(false, 3, 2) == false, "distinct name");
    }

    test registry_is_authoritative {
        assert(claim_status(true, false, true, true) == CLAIM_VERIFIED, "global claim");
        assert(claim_status(true, false, false, false) == CLAIM_MESH_LOCAL, "offline claim");
        assert(claim_status(true, false, true, false) == CLAIM_REJECTED, "registry rejected");
    }

    test signed_claim_routes {
        assert(may_route_by_nickname(CLAIM_VERIFIED, true) == true, "verified route");
        assert(may_route_by_nickname(CLAIM_MESH_LOCAL, true) == true, "mesh route");
        assert(may_route_by_nickname(CLAIM_VERIFIED, false) == false, "unsigned route");
    }

    test linked_devices_share_nickname_owner {
        assert(nickname_owner_matches(10, 10) == true, "same account");
        assert(nickname_owner_matches(10, 20) == false, "different account");
        assert(nickname_owner_matches(0, 0) == false, "missing identity");
    }

    test public_lookup_requires_exact_normalized_nickname {
        assert(exact_lookup_may_return(true, true, 2) == true, "exact account summary");
        assert(exact_lookup_may_return(true, false, 2) == false, "substring is private");
        assert(exact_lookup_may_return(false, true, 2) == false, "invalid query");
        assert(exact_lookup_may_return(true, true, 0) == false, "inactive account hidden");
    }

    test cached_mesh_route_expiry {
        assert(cached_mesh_route_is_fresh(100, 604900) == true, "ttl boundary");
        assert(cached_mesh_route_is_fresh(100, 604901) == false, "expired route");
        assert(cached_mesh_route_is_fresh(101, 100) == false, "future observation");
    }

    test auto_route_requires_live_mesh_advertisement {
        assert(auto_route_may_use_mesh(true, false) == true, "live route");
        assert(auto_route_may_use_mesh(false, true) == false, "cache is not presence");
    }

    test link_local_mesh_route_is_ephemeral {
        assert(mesh_route_may_be_cached(false) == true, "private route cache");
        assert(mesh_route_may_be_cached(true) == false, "link local expires");
    }

    test directory_result_priority_is_stable {
        assert(directory_result_rank(true, true) > directory_result_rank(false, true), "live mesh first");
        assert(directory_result_rank(false, true) > directory_result_rank(true, false), "online Internet next");
        assert(directory_result_rank(true, false) > directory_result_rank(false, false), "cache before offline");
    }

    test direct_mesh_target_requires_numeric_ipv4 {
        assert(direct_mesh_target_is_supported(true) == true, "numeric target");
        assert(direct_mesh_target_is_supported(false) == false, "hostname resolved by discovery");
    }

    invariant nickname_length_bounds
        assert NICKNAME_MIN_LENGTH < NICKNAME_MAX_LENGTH

    invariant verified_is_stronger_than_local
        assert CLAIM_VERIFIED > CLAIM_MESH_LOCAL

    invariant confusing_distance_is_small
        assert MAX_EDIT_DISTANCE < NICKNAME_MIN_LENGTH

    invariant substring_lookup_never_returns_public_account
        assert exact_lookup_may_return(true, false, 1) == false

    invariant mesh_route_cache_is_bounded
        assert MESH_ROUTE_CACHE_TTL_SECONDS <= 604800

    bench nickname_policy_latency
        measure: nanoseconds to nickname_is_confusing(false, 1, 0)
        target: < 1000ns
}

// Network Analytics - traffic analysis and pattern detection
// Monitor network behavior and identify anomalies

module NetworkAnalytics {
    use base::types;

    const MAX_NODES: u32 = 8;
    const ANALYSIS_WINDOW: u32 = 1000;
    const TRAFFIC_LOW: u32 = 100;
    // Packed fields are 8-bit, so max total traffic = 255 + 255 = 510.
    // 1000 was unreachable, making is_traffic_high dead code.
    const TRAFFIC_HIGH: u32 = 400;
    const ANOMALY_THRESHOLD: u32 = 200;

    // Traffic statistics [bytes_sent][bytes_recv][packet_count][error_count]
    fn create_traffic_stats(sent: u32, recv: u32, packets: u32, errors: u32) -> u32 {
        return (((sent & 0xFF) << 24) |
                ((recv & 0xFF) << 16) |
                ((packets & 0xFF) << 8) |
                (errors & 0xFF));
    }

    fn get_bytes_sent(stats: u32) -> u32 {
        return ((stats >> 24) & 0xFF);
    }

    fn get_bytes_recv(stats: u32) -> u32 {
        return ((stats >> 16) & 0xFF);
    }

    fn get_packet_count(stats: u32) -> u32 {
        return ((stats >> 8) & 0xFF);
    }

    fn get_error_count(stats: u32) -> u32 {
        return (stats & 0xFF);
    }

    // Analysis data [node_id][traffic_stats][window_start][pattern]
    fn create_analysis_data(node_id: u32, traffic: u32, window_start: u32, pattern: u32) -> u64 {
        return (((node_id as u64) << 48) |
                ((traffic as u64) << 24) |
                ((window_start as u64) << 12) |
                (pattern as u64));
    }

    fn get_analysis_node_id(data: u64) -> u32 {
        return ((data >> 48) & 0xFF) as u32;
    }

    fn get_analysis_traffic(data: u64) -> u32 {
        return ((data >> 24) & 0xFF) as u32;
    }

    fn get_analysis_window_start(data: u64) -> u32 {
        return ((data >> 12) & 0xFFF) as u32;
    }

    fn get_analysis_pattern(data: u64) -> u32 {
        return (data & 0xFFF) as u32;
    }

    // Pattern constants
    const PATTERN_NORMAL: u32 = 0;
    const PATTERN_SPIKE: u32 = 1;
    const PATTERN_DROPOUT: u32 = 2;
    const PATTERN_CONGESTION: u32 = 3;

    // Calculate total traffic
    fn calculate_total_traffic(stats: u32) -> u32 {
        return get_bytes_sent(stats) + get_bytes_recv(stats);
    }

    // Check if traffic is low
    fn is_traffic_low(stats: u32) -> bool {
        return (calculate_total_traffic(stats) < TRAFFIC_LOW);
    }

    // Check if traffic is high
    fn is_traffic_high(stats: u32) -> bool {
        return (calculate_total_traffic(stats) > TRAFFIC_HIGH);
    }

    // Check if traffic is normal
    fn is_traffic_normal(stats: u32) -> bool {
        let total = calculate_total_traffic(stats);
        return (total >= TRAFFIC_LOW) && (total <= TRAFFIC_HIGH);
    }

    // Calculate error rate
    fn calculate_error_rate(stats: u32) -> u32 {
        let packets = get_packet_count(stats);
        let errors = get_error_count(stats);

        if (packets == 0) {
            return 0; // No traffic, no error rate
        }

        return ((errors * 100) / packets);
    }

    // Check if error rate is high
    fn is_high_error_rate(stats: u32) -> bool {
        return (calculate_error_rate(stats) > 10); // 10% threshold
    }

    // Detect traffic pattern
    fn detect_pattern(stats: u32, previous_stats: u32) -> u32 {
        let current_total = calculate_total_traffic(stats);
        let previous_total = calculate_total_traffic(previous_stats);

        // Check for spike
        if (current_total > previous_total + ANOMALY_THRESHOLD) {
            return PATTERN_SPIKE;
        }

        // Check for dropout (addition form: previous - threshold underflows when previous < threshold)
        if (current_total + ANOMALY_THRESHOLD < previous_total) {
            return PATTERN_DROPOUT;
        }

        // Check for congestion (high errors)
        if (is_high_error_rate(stats)) {
            return PATTERN_CONGESTION;
        }

        return PATTERN_NORMAL;
    }

    // Update traffic statistics
    fn update_traffic(stats: u32, sent_add: u32, recv_add: u32, packets_add: u32, errors_add: u32) -> u32 {
        let sent = get_bytes_sent(stats);
        let recv = get_bytes_recv(stats);
        let packets = get_packet_count(stats);
        let errors = get_error_count(stats);

        return create_traffic_stats(
            sent + sent_add,
            recv + recv_add,
            packets + packets_add,
            errors + errors_add
        );
    }

    // Check if node needs attention
    fn needs_attention(data: u64) -> bool {
        let pattern = get_analysis_pattern(data);
        let traffic = get_analysis_traffic(data);
        let stats = traffic; // Reuse as stats

        return (pattern != PATTERN_NORMAL) || is_high_error_rate(stats);
    }

    // Calculate network utilization (rough estimate)
    fn calculate_utilization(stats: u32, max_capacity: u32) -> u32 {
        let total = calculate_total_traffic(stats);

        if (max_capacity == 0) {
            return 0; // Avoid division by zero
        }

        return ((total * 100) / max_capacity);
    }

    // Check if network is congested
    fn is_congested(stats: u32, max_capacity: u32) -> bool {
        return (calculate_utilization(stats, max_capacity) > 80); // 80% threshold
    }

    // ---- Tests ----

    test create_traffic_stats_basic {
        stats = create_traffic_stats(100, 200, 50, 5);
        assert(get_bytes_sent(stats) == 100, "sent");
        assert(get_bytes_recv(stats) == 200, "received");
        assert(get_packet_count(stats) == 50, "packets");
        assert(get_error_count(stats) == 5, "errors");
    }

    test calculate_total_traffic {
        stats = create_traffic_stats(100, 200, 50, 5);
        assert(calculate_total_traffic(stats) == 300, "total traffic");
    }

    test is_traffic_low_true {
        stats = create_traffic_stats(30, 40, 10, 0);
        assert(is_traffic_low(stats) == true, "low traffic");
    }

    test is_traffic_high_true {
        // Values must fit 8-bit fields; 250 + 200 = 450 > TRAFFIC_HIGH (400).
        stats = create_traffic_stats(250, 200, 100, 5);
        assert(is_traffic_high(stats) == true, "high traffic");
    }

    test is_traffic_normal {
        stats = create_traffic_stats(200, 300, 50, 2);
        assert(is_traffic_normal(stats) == true, "normal traffic");
    }

    test calculate_error_rate {
        stats = create_traffic_stats(100, 200, 50, 5);
        assert(calculate_error_rate(stats) == 10, "10% error rate");
    }

    test calculate_error_rate_no_traffic {
        stats = create_traffic_stats(0, 0, 0, 0);
        assert(calculate_error_rate(stats) == 0, "no error rate");
    }

    test is_high_error_rate_true {
        stats = create_traffic_stats(100, 200, 40, 5); // 12.5% error rate
        assert(is_high_error_rate(stats) == true, "high error rate");
    }

    test is_high_error_rate_false {
        stats = create_traffic_stats(100, 200, 60, 3); // 5% error rate
        assert(is_high_error_rate(stats) == false, "normal error rate");
    }

    test detect_pattern_spike {
        // Values must fit 8-bit fields: 250 + 240 = 490 > 200 + ANOMALY_THRESHOLD (200).
        current = create_traffic_stats(250, 240, 100, 2);
        previous = create_traffic_stats(100, 100, 20, 0);
        assert(detect_pattern(current, previous) == PATTERN_SPIKE, "spike detected");
    }

    test detect_pattern_dropout {
        // Values must fit 8-bit fields: 100 + ANOMALY_THRESHOLD (200) < 250 + 250 = 500.
        current = create_traffic_stats(50, 50, 10, 0);
        previous = create_traffic_stats(250, 250, 80, 2);
        assert(detect_pattern(current, previous) == PATTERN_DROPOUT, "dropout detected");
    }

    test detect_pattern_congestion {
        current = create_traffic_stats(200, 200, 40, 5); // 12.5% errors
        previous = create_traffic_stats(200, 200, 40, 2);
        assert(detect_pattern(current, previous) == PATTERN_CONGESTION, "congestion detected");
    }

    test detect_pattern_normal {
        current = create_traffic_stats(200, 250, 50, 2);
        previous = create_traffic_stats(180, 230, 45, 1);
        assert(detect_pattern(current, previous) == PATTERN_NORMAL, "normal pattern");
    }

    test update_traffic_works {
        stats = create_traffic_stats(100, 200, 50, 5);
        new_stats = update_traffic(stats, 50, 30, 10, 1);
        assert(get_bytes_sent(new_stats) == 150, "sent updated");
        assert(get_bytes_recv(new_stats) == 230, "received updated");
        assert(get_packet_count(new_stats) == 60, "packets updated");
        assert(get_error_count(new_stats) == 6, "errors updated");
    }

    test calculate_utilization {
        // Values must fit 8-bit fields: total 400, capacity 800 -> 50%.
        stats = create_traffic_stats(200, 200, 100, 5);
        assert(calculate_utilization(stats, 800) == 50, "50% utilization");
    }

    test calculate_utilization_zero_capacity {
        stats = create_traffic_stats(400, 600, 100, 5);
        assert(calculate_utilization(stats, 0) == 0, "no capacity");
    }

    test is_congested_true {
        // Values must fit 8-bit fields: total 500 of capacity 500 = 100% > 80%.
        stats = create_traffic_stats(250, 250, 200, 10);
        assert(is_congested(stats, 500) == true, "network congested");
    }

    test is_congested_false {
        stats = create_traffic_stats(400, 500, 100, 5);
        assert(is_congested(stats, 2000) == false, "network not congested");
    }
}

